import { ExplorerItem, RpcNode } from '@cetus/types/src/common-types'
import { defaultExplorer, defaultExplorers, defaultNode, defaultNodes } from '@cetus/types/src/config'
import { StateCreator, create } from 'zustand'
import { persist } from 'zustand/middleware'

interface ConfigState {
  /**
   * RPC 节点
   */
  currentNode: RpcNode
  nodes: RpcNode[]
  switchNode: (node: RpcNode) => void
  setNodeList: (nodeList: RpcNode[]) => void

  /**
   * 区块游览器
   */
  currentExplorer: ExplorerItem
  explorerList: ExplorerItem[]
  switchExplorer: (explorer: ExplorerItem) => void
}

const store: StateCreator<ConfigState> = (set, get) => ({
  currentExplorer: defaultExplorer,
  explorerList: [...defaultExplorers],
  currentNode: { ...defaultNode },
  nodes: [...defaultNodes],
  switchNode: (node: RpcNode) => {
    set(() => ({
      currentNode: node
    }))
  },
  switchExplorer: (explorer: ExplorerItem) => {
    set(() => ({
      currentExplorer: explorer
    }))
  },
  setNodeList: (nodeList: RpcNode[]) => {
    set(() => ({
      nodes: [...nodeList]
    }))
  }
})

const useRpcConfigStore = create(persist(store, { name: 'useRpcConfigStore', version: 3 }))
export default useRpcConfigStore
