import {
  d,
  extractStructTagFromType,
  getDeltaDownFromOutput,
  getDeltaUpFromInput,
  getLiquidityFromCoinB,
  getNextSqrtPriceFromInput,
  getNextSqrtPriceFromOutput
} from '@cetusprotocol/cetus-sui-clmm-sdk'
import BN from 'bn.js'
import Decimal from 'decimal.js'
import { BondingCurve, BondingCurveStatus, CalculateSwapAmountResult, PumpGlobalConfig } from '..'

export const FEE_RATE_DENOMINATOR: number = 1000000
export const RATE_PRECISION = 100000000000000000000

export class PumpUtils {
  static getCurveInfoStatus(status: number) {
    switch (status) {
      case 0:
        return BondingCurveStatus.CREATED
      case 1:
        return BondingCurveStatus.RAISING
      case 2:
        return BondingCurveStatus.COMPLETED
      case 3:
        return BondingCurveStatus.MIGRATED
      case 4:
        return BondingCurveStatus.LP_BURNED

      default:
        return BondingCurveStatus.RAISING
    }
  }

  static buildBondingCurveInfo(res: any) {
    const data = res.data
    const fields = data.content.fields
    const coin_type = extractStructTagFromType(data.type).type_arguments[0]

    const info: BondingCurve = {
      id: fields.id.id,
      coin_type,
      balance: fields.balance,
      sui_balance: fields.sui_balance,
      pending_fee: fields.pending_fee,
      total_fee: fields.total_fee,
      start_sqrt_price: fields.start_sqrt_price,
      end_sqrt_price: fields.end_sqrt_price,
      current_sqrt_price: fields.current_sqrt_price,
      liquidity: fields.liquidity,
      volume: fields.volume,
      media_metadata: {
        website: fields.media_metadata.fields.website,
        twitter: fields.media_metadata.fields.twitter,
        telegram: fields.media_metadata.fields.telegram,
        discord: fields.media_metadata.fields.discord
      },
      status: BondingCurveStatus.CREATED,
      creator: fields.creator,
      clmm_pool_id: fields.clmm_pool_id,
      url: fields.url
    }

    info.status = this.getCurveInfoStatus(fields.status)
    return info
  }

  static buildGlobalConfig(res: any) {
    const data = res.data
    const fields = data.content.fields
    const info: PumpGlobalConfig = {
      id: fields.id.id,
      swap_fee_rate: fields.swap_fee_rate,
      is_protocol_owned_lp: fields.is_protocol_owned_lp,
      init_fees_handle: fields.init_fees.fields.id.id,
      fee_vault_handle: fields.fee_vault.fields.id.id,
      acl_handle: fields.acl.fields.permissions.fields.id.id,
      bonding_curve_config: fields.bonding_curve_config.fields
    }

    return info
  }

  static calculateCurveSwapAmount(
    start_sqrt_price: string,
    current_sqrt_price: string,
    end_sqrt_price: string,
    liquidity: string,
    swap_fee_rate: number,
    amount: string,
    by_amount_in: boolean,
    is_buy: boolean,
    slippage: number,
    status?: BondingCurveStatus
  ) {
    if (is_buy) {
      const { amount_in, amount_out, fee_amount, next_sqrt_price } = this.buy(
        current_sqrt_price,
        end_sqrt_price,
        liquidity,
        d(amount).toFixed(0),
        swap_fee_rate,
        by_amount_in
      )

      const total_amount_in = d(amount_in).add(fee_amount)
      const slippage_price = d(total_amount_in)
        .div(amount_out)
        .mul(1 + slippage)
      const expect_rate_limit = slippage_price.mul(RATE_PRECISION).toFixed(0)

      const do_complete_action = status === BondingCurveStatus.COMPLETED ? false : d(next_sqrt_price).gte(end_sqrt_price)
      return {
        amount_in,
        amount_out,
        fee_amount,
        expect_rate_limit,
        next_sqrt_price,
        do_complete_action,
        slippage_price: slippage_price.toString()
      }
    } else {
      const { amount_in, amount_out, fee_amount, next_sqrt_price } = this.sell(
        current_sqrt_price,
        start_sqrt_price,
        liquidity,
        d(amount).toFixed(0),
        swap_fee_rate,
        by_amount_in
      )

      const slippage_price = d(amount_out)
        .div(amount_in)
        .mul(1 - slippage)
      const expect_rate_limit = slippage_price.mul(RATE_PRECISION).toFixed(0)

      const do_complete_action = status === BondingCurveStatus.COMPLETED ? false : d(next_sqrt_price).gte(end_sqrt_price)
      return {
        amount_in,
        amount_out,
        fee_amount,
        expect_rate_limit,
        next_sqrt_price,
        do_complete_action,
        slippage_price: slippage_price.toString()
      }
    }
  }

  static getFeeAmount(amount: string, fee_rate: number) {
    return d(amount)
      .mul(fee_rate)
      .div(FEE_RATE_DENOMINATOR - fee_rate)
  }

  static buy(current_sqrt_price: string, target_sqrt_price: string, liquidity: string, amount: string, fee_rate: number, by_amount_in: boolean) {
    if (d(target_sqrt_price).lte(current_sqrt_price)) {
      throw Error('EInvalidSqrtPriceInput')
    }
    if (d(liquidity).eq(0)) {
      throw Error('ELiquidityIsZero')
    }

    const a2b = false
    let amount_in, amount_out, fee_amount, next_sqrt_price

    if (by_amount_in) {
      const amount_remain = d(amount)
        .mul(FEE_RATE_DENOMINATOR - fee_rate)
        .div(FEE_RATE_DENOMINATOR)

      const max_amount_in = getDeltaUpFromInput(new BN(current_sqrt_price), new BN(target_sqrt_price), new BN(liquidity), a2b).toString()

      if (d(max_amount_in).gt(amount_remain)) {
        amount_in = amount_remain
        fee_amount = d(amount).sub(amount_remain)
        next_sqrt_price = getNextSqrtPriceFromInput(new BN(current_sqrt_price), new BN(liquidity), new BN(amount_remain.toFixed(0)), a2b).toString()
      } else {
        amount_in = max_amount_in
        fee_amount = PumpUtils.getFeeAmount(amount_in, fee_rate)
        next_sqrt_price = target_sqrt_price
      }

      amount_out = getDeltaDownFromOutput(new BN(current_sqrt_price), new BN(next_sqrt_price), new BN(liquidity), a2b)
    } else {
      const max_amount_out = getDeltaDownFromOutput(new BN(current_sqrt_price), new BN(target_sqrt_price), new BN(liquidity), a2b).toString()

      if (d(max_amount_out).gt(amount)) {
        amount_out = amount
        next_sqrt_price = getNextSqrtPriceFromOutput(new BN(current_sqrt_price), new BN(liquidity), new BN(amount), a2b)
      } else {
        amount_out = max_amount_out
        next_sqrt_price = target_sqrt_price
      }
      amount_in = getDeltaUpFromInput(new BN(current_sqrt_price), new BN(next_sqrt_price), new BN(liquidity), false)

      fee_amount = d(amount_in.toString())
        .mul(fee_rate)
        .div(FEE_RATE_DENOMINATOR - fee_rate)

      console.log('🚀 ~ file: pumpUtils.ts:193 ~ PumpUtils ~ buy ~ amount_in:', amount_in.toString(), fee_amount.toString())
    }

    return {
      amount_in: d(amount_in.toString()).toFixed(0),
      amount_out: d(amount_out.toString()).toFixed(0),
      next_sqrt_price: next_sqrt_price.toString(),
      fee_amount: fee_amount.toFixed(0, Decimal.ROUND_UP)
    }
  }

  static sell(current_sqrt_price: string, target_sqrt_price: string, liquidity: string, amount: string, fee_rate: number, by_amount_in: boolean) {
    if (d(target_sqrt_price).gte(current_sqrt_price)) {
      throw Error('EInvalidSqrtPriceInput')
    }
    if (d(liquidity).eq(0)) {
      throw Error('ELiquidityIsZero')
    }

    const a2b = true
    let amount_in, amount_out, fee_amount, next_sqrt_price

    if (by_amount_in) {
      const max_amount_in = getDeltaUpFromInput(new BN(current_sqrt_price), new BN(target_sqrt_price), new BN(liquidity), a2b).toString()

      if (d(max_amount_in).gt(amount)) {
        amount_in = amount
        next_sqrt_price = getNextSqrtPriceFromInput(new BN(current_sqrt_price), new BN(liquidity), new BN(amount), a2b)
      } else {
        amount_in = max_amount_in
        next_sqrt_price = target_sqrt_price
      }

      const amount_out_with_fee = getDeltaDownFromOutput(new BN(current_sqrt_price), new BN(next_sqrt_price), new BN(liquidity), a2b).toString()

      fee_amount = d(amount_out_with_fee).mul(fee_rate).div(FEE_RATE_DENOMINATOR)
      amount_out = d(amount_out_with_fee).sub(fee_amount)
    } else {
      const need_amount_out = d(amount)
        .mul(FEE_RATE_DENOMINATOR)
        .div(FEE_RATE_DENOMINATOR - fee_rate)
      const max_amount_out = getDeltaDownFromOutput(new BN(current_sqrt_price), new BN(target_sqrt_price), new BN(liquidity), a2b).toString()

      if (d(max_amount_out).gt(need_amount_out)) {
        amount_out = amount
        fee_amount = d(need_amount_out).sub(amount)
        next_sqrt_price = getNextSqrtPriceFromOutput(new BN(current_sqrt_price), new BN(liquidity), new BN(need_amount_out.toFixed(0)), a2b)
      } else {
        const amount_out_with_fee = max_amount_out
        fee_amount = d(amount_out_with_fee).mul(fee_rate).div(FEE_RATE_DENOMINATOR)
        amount_out = d(amount_out_with_fee).sub(fee_amount)
        next_sqrt_price = target_sqrt_price
      }
      amount_in = getDeltaUpFromInput(new BN(current_sqrt_price), new BN(next_sqrt_price), new BN(liquidity), a2b)
    }

    return {
      amount_in: d(amount_in.toString()).toFixed(0),
      amount_out: d(amount_out.toString()).toFixed(0),
      next_sqrt_price: next_sqrt_price.toString(),
      fee_amount: fee_amount.toFixed(0, Decimal.ROUND_UP)
    }
  }

  static get_init_liquidity_from_sui(start_sqrt_price: string, end_sqrt_price: string, sui_amount: string) {
    const liquidity = getLiquidityFromCoinB(new BN(sui_amount), new BN(start_sqrt_price), new BN(end_sqrt_price), false)
    return liquidity.toString()
  }

  static calculateAmountLimit(isBuy: boolean, swapResult: CalculateSwapAmountResult) {
    const { by_amount_in, amount_in, fee_amount, slippage_price, amount_out } = swapResult
    if (isBuy) {
      if (by_amount_in) {
        return d(amount_in).add(fee_amount).div(slippage_price).toFixed(0)
      } else {
        return d(amount_out).mul(slippage_price).add(fee_amount).toFixed(0)
      }
    } else {
      if (by_amount_in) {
        return d(amount_in).mul(slippage_price).sub(fee_amount).toFixed(0)
      } else {
        return d(amount_out).add(fee_amount).div(slippage_price).toFixed(0)
      }
    }
  }
}
