import { Icon } from '@cetus/ui-kit'
import { Box, FormErrorMessage, FormLabel, FormLabelProps, HStack, Input, InputGroup, InputLeftElement, Text } from '@chakra-ui/react'
import { FormInputProps } from './type'
import { formInputStyle } from './utils'

export const FormInput = ({ icon, placeholder, field, isInvalid }: FormInputProps) => {
  return (
    <InputGroup gap="16px">
      <InputLeftElement pointerEvents="none" top="14px" left="20px">
        <Icon xlinkHref={icon} />
      </InputLeftElement>

      <Input
        {...field}
        placeholder={placeholder}
        {...formInputStyle}
        pl="56px"
        _focusVisible={{
          borderColor: 'primary',
          boxShadow: `0px 1px 0px 0px primary`
        }}
        {...(isInvalid ? { borderColor: 'input_error_border', boxShadow: 'input_error_border 0px 0px 0px 1px' } : {})}
      />
    </InputGroup>
  )
}

export const Required = () => {
  return (
    <Text color="primary_green" fontSize="12px" fontWeight="500" as="span">
      （Required）
    </Text>
  )
}
const toastConfig = {
  success: {
    icon: '#icon-icon_check',
    color: 'primary_green'
  },
  error: {
    icon: '#icon-icon_close',
    color: 'primary_red'
  }
}
export const UploadLimitToast = ({ title, onClose, status }: { title: string; onClose: () => void; status: 'success' | 'error' }) => {
  const config = toastConfig[status]
  return (
    <HStack
      p="16px"
      h="52px"
      bg="bg_secondary"
      borderRadius="12px"
      border="1px solid"
      borderColor="border"
      gap={{ base: '20px', lg: '100px' }}
      justify="space-between"
      align="center"
    >
      <HStack align="center" gap="8px">
        <Icon xlinkHref={config.icon} svgFill={config.color} />
        <Text h="20px" lineHeight="20px" color={config.color}>
          {title}
        </Text>
      </HStack>
      <Icon xlinkHref="#icon-icon_close" onClick={onClose} />
    </HStack>
  )
}

export const Label = (props: FormLabelProps) => {
  return <FormLabel color="text_caption" fontFamily="Inter, sans-serif" {...props} />
}

export const FormValueGroup = ({
  children,
  isInvalid,
  message,
  placeholder = true
}: {
  children: React.ReactNode
  isInvalid?: boolean
  message?: string
  placeholder?: boolean
}) => {
  return (
    <Box borderRadius="12px" bg={isInvalid ? 'primary_red_opacity.10' : 'transparent'}>
      {children}
      {isInvalid ? (
        <FormErrorMessage minH="28px" mt="0px" p="7px 0px 7px 20px" lineHeight="14px" fontSize="12px" color="primary_red">
          {message}
        </FormErrorMessage>
      ) : (
        <Box h={placeholder ? { base: '0', lg: '28px' } : '0px'} />
      )}
    </Box>
  )
}
