import { ButtonProps, FlexboxProps, StackProps, StyleProps, TextProps } from '@chakra-ui/react'
import { Key, ReactNode } from 'react'

export enum HandleEventType {
  Add = 'add',
  Edit = 'edit',
  Delete = 'delete'
}
interface HandleEvent {
  onChange?: (type: HandleEventType, ...args: any[]) => void
}

export interface ILabel {
  text?: string
  render?: FunctionNode
  tooltip: FunctionNode
}

interface CommonItem extends HandleEvent {
  key?: Key | ((...args: any) => Key)
  label: FunctionNode | ILabel
}
export type FunctionNode = ReactNode | ((...args: any[]) => ReactNode)

export type ValueOption = {
  text?: string
  render?: FunctionNode
  editable?: boolean
} & TextProps

export interface ItemWithSingleLine extends CommonItem {
  type: SingleLineValueCells
  value: FunctionNode | ValueOption
  color?: string
}

export interface ItemWithDoubleLine extends CommonItem {
  type: DoubleLineValueCells
  value: (FunctionNode | ValueOption)[]
}

export interface ItemForAction extends CommonItem {
  type: SingleLineValueCells
  value: FunctionNode | ValueOption
  color?: string
  btn: {
    text: ReactNode
    color?: string
    bg_color?: string
  }
  bg_color?: string
}

export interface ItemForCos extends CommonItem {
  type: H5MapTableCells.Cos
  value: FunctionNode
  showLabel?: boolean
  hidden?: boolean
}

export type H5MapTableItem = ItemWithSingleLine | ItemWithDoubleLine | ItemForAction | ItemForCos

export type ItemWithSingleLineProps = {
  value: FunctionNode | ValueOption
  color?: string
} & HandleEvent

export type ItemWithDoubleLineProps = {
  value: (FunctionNode | ValueOption)[]
} & HandleEvent

export type ItemForActionProps = {
  value: FunctionNode | ValueOption
  color?: string
  btn: {
    text: ReactNode
    color?: string
    bg_color?: string
  }
} & HandleEvent

export enum H5MapTableCells {
  Regular = 'regular',
  Double = 'double',
  Divider = 'divider',
  Action = 'action',
  Cos = 'cos'
}

type SingleLineValueCells = H5MapTableCells.Regular | H5MapTableCells.Action

type DoubleLineValueCells = Exclude<H5MapTableCells, SingleLineValueCells | H5MapTableCells.Cos>

export type Action_Value = {
  btn: ReactNode
  color: string
  bg_color: string
}

export enum TitleEnum {
  SingleToken = 'SingleToken',
  ST = 'ST',
  DoubleToken = 'DoubleToken',
  DT = 'DT'
}
export type SingleTitleType = TitleEnum.SingleToken | TitleEnum.ST
export type DoubleTitleType = TitleEnum.DoubleToken | TitleEnum.DT

interface ITitleData {
  symbol: string
  imageUrl: string
}
export interface SingleTokenData extends ITitleData {
  name?: string
  loading: boolean
}

export interface DoubleTokenData extends ITitleData {
  metadata?: string
}

export type ISingleTitle = {
  type: SingleTitleType
  data: SingleTokenData
}

export type IDoubleTitle = {
  type: DoubleTitleType
  data: [DoubleTokenData, DoubleTokenData]
  fee: string
  loading: boolean
}

export type ITitle = ISingleTitle | IDoubleTitle

export type IBottomBtnItem = {
  text?: string
  render?: FunctionNode
  key?: string
} & ButtonProps

export type IBottomBtn = {
  style?: StyleProps
  data: IBottomBtnItem[]
}

export type H5MapTableProps = {
  data: H5MapTableItem[]
  children?: ReactNode
  loading?: boolean
  skeletonLength?: number
  itemHeight?: FlexboxProps['flexBasis']
  style?: StackProps
  title?: ITitle
  bottom?: FunctionNode | IBottomBtn | IBottomBtnItem
  onClick: () => void | undefined
}

export type ILogo = {
  name: ReactNode
  logo: string
  multiple: number
  isLong: boolean
}
