import { useDebounceFunction } from '@cetus/hooks/src/useDebounce'
import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import { useGetTokenBalance } from '@cetus/hooks/src/useTokenBalance'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { useAccountStore } from '@cetus/stores'
import { CoinInfo } from '@cetus/types'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { Decimal, formatNumber, fromDecimalsAmountFix } from '@cetus/utils'
import { d } from '@cetus/utils/src/number'
import { toDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { CalculateSwapAmountOptions, CalculateSwapAmountResult, PumpUtils } from '@cetusprotocol/cetus-sui-pump-sdk'
import { useEffect, useMemo, useRef, useState } from 'react'
import { v4 } from 'uuid'
import { useGetGlobalConfig } from './useGetGlobalConfig'
import { useGetAmountLimit } from './usePumpTokenHelper'

/**
 *
 * @param isBuy
 * @param token_info_id
 * @param baseCoinType
 * @param quoteCoinType
 * @returns
 */
export function usePumpTrade(
  max_amount_config: {
    buyMaxAmountIn: string
    buyMaxAmountOut: string
    sellMaxAmountIn: string
    sellMaxAmountOut: string
  },
  isBuy: boolean,
  slippage: number,
  remain_sui: string,
  bonding_curve_id?: string,
  baseCoin?: CoinInfo,
  quoteCoin = envConfigs.sui_coin,
  use_default_price = false
) {
  const { buyMaxAmountIn, buyMaxAmountOut, sellMaxAmountIn, sellMaxAmountOut } = max_amount_config

  const { currentAccount } = useAccountStore()
  const { pumpSdk } = useInitSDK()
  const { fetchTokenPrices, getTokenAmountValue } = useTokenPrice()
  const { globalConfig } = useGetGlobalConfig()

  const [byAmountIn, setByAmountIn] = useState(true)

  // amount
  const [payAmount, setPayAmount] = useState<string>('')
  const [receiveAmount, setReceiveAmount] = useState<string>('')
  const [uuid, setUuid] = useState<string>('')

  const payAmountRef = useRef<string>('')
  const receiveAmountRef = useRef<string>('')
  const uuidRef = useRef<string>('')
  const byAmountInRef = useRef<boolean>(true)

  useEffect(() => {
    uuidRef.current = uuid
  }, [uuid])

  useEffect(() => {
    byAmountInRef.current = byAmountIn
  }, [byAmountIn])

  useEffect(() => {
    payAmountRef.current = payAmount
  }, [payAmount])

  useEffect(() => {
    receiveAmountRef.current = receiveAmount
  }, [receiveAmount])

  // 预计算进度
  const [calculateLoading, setCalculateLoading] = useState<boolean>(false)
  // 预计算结果
  const [calculateSwapResult, setCalculateSwapResult] = useState<CalculateSwapAmountResult | undefined>()

  // 支付coin
  const payCoin = useMemo(() => {
    return isBuy ? quoteCoin : baseCoin
  }, [isBuy, quoteCoin, baseCoin])

  // 接受coin
  const receiveCoin = useMemo(() => {
    return isBuy ? baseCoin : quoteCoin
  }, [isBuy, quoteCoin, baseCoin])

  // 获取coin的价格
  useEffect(() => {
    if (baseCoin && quoteCoin) {
      fetchTokenPrices([quoteCoin.coin_type])
    }
  }, [quoteCoin?.coin_type])

  //最小接受
  const { amountLimit } = useGetAmountLimit(isBuy, calculateSwapResult)

  // 价值 TODO 新创建的Token 还没价格，如何获取
  const payAmountValue = getTokenAmountValue(payCoin?.coin_type, payAmount)
  const receiveAmountValue = getTokenAmountValue(receiveCoin?.coin_type, receiveAmount)

  // 余额
  const { balanceInfo: payBalance } = useGetTokenBalance(payCoin)

  const { balanceInfo: receiveBalance } = useGetTokenBalance(receiveCoin)

  const [warnInfo, setWarnInfo] = useState<{ warnText: string; amount: string } | undefined>()

  // 预计算输入校验
  const verifyPreInput = (amount: string, by_amount_in: boolean) => {
    if (by_amount_in) {
      // 余额不足
      if (d(amount).gt(payBalance?.balance || 0)) {
        setWarnInfo(undefined)
        setReceiveAmount('')
        return false
      }

      if (isBuy) {
        if (d(amount).gt(buyMaxAmountIn)) {
          setWarnInfo({
            warnText: `Maximum input ${formatNumber(fromDecimalsAmountFix(buyMaxAmountIn, 9), 9, false)} SUI `,
            amount: buyMaxAmountIn
          })
          setReceiveAmount('')
          return false
        }

        // 最少留0.05 sui 做gas
        if (
          d(payBalance?.balance || 0)
            .sub(amount)
            .lt(toDecimalsAmount(remain_sui, 9))
        ) {
          setWarnInfo({
            warnText: `You need at least ${remain_sui}  SUI to guarantee the transaction is successfully.`,
            amount: '0'
          })
          setReceiveAmount('')
          return false
        }
      } else {
        // if (d(amount).gt(sellMaxAmountIn)) {
        //   setWarnText(`Maximum sell: ${fromDecimalsAmountFix(sellMaxAmountIn, 9)} ${payCoin?.symbol}`)
        //   setReceiveAmount('')
        //   setCalculateLoading(false)
        //   setCalculateSwapResult(undefined)
        //   return false
        // }
      }
    } else {
      if (isBuy) {
        if (d(amount).gt(buyMaxAmountOut)) {
          setWarnInfo({
            warnText: `Maximum buy: ${formatNumber(fromDecimalsAmountFix(buyMaxAmountOut, 9), 9, false)} ${receiveCoin?.symbol}`,
            amount: buyMaxAmountOut
          })
          setPayAmount('')
          return false
        }
      } else {
        // if (d(amount).gt(sellMaxAmountOut)) {
        //   setWarnText(`Maximum buy: ${fromDecimalsAmountFix(sellMaxAmountOut, 9)} ${receiveCoin?.symbol}`)
        //   setPayAmount('')
        //   setCalculateLoading(false)
        //   setCalculateSwapResult(undefined)
        //   return false
        // }
      }
    }
    setWarnInfo(undefined)
    return true
  }

  // 预计算
  const doPreCalculate = async (amount: string, by_amount_in: boolean, uuid: string) => {
    if (!verifyPreInput(toDecimalsAmount(amount, 9).toString(), by_amount_in)) {
      setCalculateLoading(false)
      setCalculateSwapResult(undefined)
      return
    }
    console.log('🚀 ~ file: usePumpTrade.ts:12202 ~ doPreCalculate ~ request:', {
      amount,
      baseCoin,
      quoteCoin,
      bonding_curve_id
    })
    if (+amount && baseCoin && quoteCoin && bonding_curve_id) {
      setCalculateLoading(true)

      const fixToken = isBuy ? (by_amount_in ? quoteCoin : baseCoin) : by_amount_in ? baseCoin : quoteCoin
      const amountF = toDecimalsAmount(amount, fixToken.decimals).toString()

      let init_price_config

      if (use_default_price) {
        const start_sqrt_price = globalConfig!.bonding_curve_config.start_sqrt_price
        const current_sqrt_price = globalConfig!.bonding_curve_config.start_sqrt_price
        const end_sqrt_price = globalConfig!.bonding_curve_config.end_sqrt_price
        const sui_amount = globalConfig!.bonding_curve_config.sui_amount
        const liquidity = PumpUtils.get_init_liquidity_from_sui(start_sqrt_price, end_sqrt_price, sui_amount)

        init_price_config = {
          start_sqrt_price,
          current_sqrt_price,
          end_sqrt_price,
          liquidity
        }
      }

      const options: CalculateSwapAmountOptions = {
        amount: amountF,
        is_buy: isBuy,
        bonding_curve_id,
        by_amount_in,
        slippage,
        swap_fee_rate: Number(globalConfig!.swap_fee_rate),
        init_price_config,
        uuid
      }

      const result = await pumpSdk.pumpModule.calculateSwapAmount(options)

      console.log('🚀 ~ file: usePumpTrade.ts:102 ~ doPreCalculate ~ result:', {
        result,
        uuid: uuidRef.current
      })
      if (uuidRef.current === result.uuid) {
        if (by_amount_in) {
          if (+payAmountRef.current) {
            setReceiveAmount(fromDecimalsAmountFix(result.amount_out, fixToken.decimals).toString())
          } else {
            setReceiveAmount('')
          }
        } else {
          if (+receiveAmountRef.current) {
            setPayAmount(
              fromDecimalsAmountFix(
                isBuy ? d(result.amount_in).add(result.fee_amount).toFixed(0, Decimal.ROUND_UP) : result.amount_in,
                fixToken.decimals
              ).toString()
            )
          } else {
            setPayAmount('')
          }
        }
      }

      setCalculateSwapResult(result)
      setCalculateLoading(false)
    } else {
      setCalculateLoading(false)
      resetAmountInput(!by_amount_in)
      setCalculateSwapResult(undefined)
    }
  }

  const debouncedPreCalculate = useDebounceFunction(doPreCalculate, 500)

  // 处理amount 输入
  const handleAmountChange = (amount: string, by_amount_in: boolean, resetInput: boolean = false) => {
    setWarnInfo(undefined)
    if (by_amount_in) {
      setByAmountIn(true)
      setPayAmount(amount)
      if (resetInput) {
        setReceiveAmount('')
      }
    } else {
      setByAmountIn(false)
      setReceiveAmount(amount)
      if (resetInput) {
        setPayAmount('')
      }
    }

    if (+amount) {
      const uuid = v4()
      setUuid(uuid)
      debouncedPreCalculate(amount, by_amount_in, uuid)
    } else {
      setCalculateLoading(false)
      resetAmountInput()
      setCalculateSwapResult(undefined)
    }
  }

  const refreshPreCalculate = () => {
    if (calculateLoading) {
      return
    }
    const amount = byAmountInRef.current ? payAmountRef.current : receiveAmountRef.current
    if (+amount) {
      const uuid = v4()
      setUuid(uuid)
      doPreCalculate(amount, byAmountInRef.current, uuid)
    } else {
      setCalculateLoading(false)
      resetAmountInput()
      setCalculateSwapResult(undefined)
    }
  }

  // 监听链接钱包，且获取到余额时，重新计算
  useEffect(() => {
    if (currentAccount && payBalance && (+payAmount || +receiveAmount)) {
      refreshPreCalculate()
    }
  }, [currentAccount, payBalance, slippage])

  const resetAmountInput = (clearPayAmount?: boolean) => {
    if (clearPayAmount === undefined) {
      setPayAmount('')
      setReceiveAmount('')
      return
    }

    if (clearPayAmount) {
      setPayAmount('')
    } else {
      setReceiveAmount('')
    }
  }

  // 切换Tab 清空输入
  useEffect(() => {
    if (+payAmount) {
      setPayAmount('')
      handleAmountChange(payAmount, false)
    } else if (+receiveAmount) {
      setReceiveAmount('')
      handleAmountChange(receiveAmount, true)
    }
    setWarnInfo(undefined)
    setCalculateSwapResult(undefined)
  }, [isBuy])

  useEffect(() => {
    if (calculateLoading && !currentAccount) {
      setCalculateLoading(false)
    }
  }, [calculateLoading, currentAccount])

  const submitBtnInfo = useMemo(() => {
    const btnInfo: {
      text?: string
      disabled: boolean
    } = {
      text: undefined,
      disabled: false
    }
    // 判断钱包
    if (!currentAccount?.address) {
      btnInfo.text = 'Connect Wallet'
      btnInfo.disabled = false
      return btnInfo
    }

    // 判断余额是否足够
    if ((+payAmount && d(payAmount).gt(payBalance?.balanceFormat || 0)) || !payBalance?.balanceFormat) {
      if (isBuy && payBalance) {
        // 最少留0.05 sui 做gas
        if (
          d(payBalance.balance || 0)
            .sub(payAmount)
            .lt(toDecimalsAmount(remain_sui, 9))
        ) {
          btnInfo.disabled = true
          btnInfo.text = 'Insufficient Balance'
          return btnInfo
        }
      }
      btnInfo.disabled = true
      btnInfo.text = 'Insufficient Balance'
      return btnInfo
    }

    //判断输入
    if (!+receiveAmount || !+payAmount) {
      btnInfo.disabled = true
      return btnInfo
    }

    return btnInfo
  }, [currentAccount?.address, receiveAmount, payAmount, payBalance?.balanceFormat])

  return {
    payAmount,
    receiveAmount,
    payCoin,
    receiveCoin,
    calculateSwapResult,
    handleAmountChange,
    calculateLoading,
    payBalance,
    receiveBalance,
    payAmountValue,
    receiveAmountValue,
    amountLimit,
    byAmountIn,
    btnText: submitBtnInfo.text,
    btnDisabled: submitBtnInfo.disabled,
    warnInfo,
    refreshPreCalculate
  }
}
