import usePumpTokenListStore from '@/store/pumpTokenList'
import { PumpToken } from '@/type/pump'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { d, fromDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurveStatus, CalculateSwapAmountResult, PumpUtils } from '@cetusprotocol/cetus-sui-pump-sdk'
import { SUI_TYPE_ARG } from '@mysten/sui/utils'
import { useMemo } from 'react'
import { useGetGlobalConfig } from './useGetGlobalConfig'

export function usePumpTokenHelper(info?: PumpToken) {
  const { globalConfig } = useGetGlobalConfig()
  const { getTokenPrice } = useTokenPrice()

  const { current_ui_price } = useGetCurrentUiPrice(info)
  const { liquidity } = useGetLiquidity(info)

  const market_cap = useMemo(() => {
    if (current_ui_price) {
      const suiPrice = getTokenPrice(SUI_TYPE_ARG)
      if (current_ui_price && globalConfig && suiPrice) {
        return d(fromDecimalsAmount(globalConfig.bonding_curve_config.amount, 9)).mul(current_ui_price).mul(suiPrice.price).toFixed(9)
      }
    }

    return undefined
  }, [current_ui_price, globalConfig])

  const raising_progress = useMemo(() => {
    if (info) {
      const status = info.status
      if (status) {
        if (status >= BondingCurveStatus.COMPLETED) {
          return '100'
        }
      }

      if (globalConfig) {
        const progress = d(d(info.sui_balance).sub(info.pending_fee)).div(globalConfig.bonding_curve_config.sui_amount).mul(100)
        return progress.gt(100) ? '100' : progress.toFixed(9).toString()
      }
    }

    return undefined
  }, [globalConfig, info])

  return {
    current_ui_price,
    market_cap,
    raising_progress,
    liquidity
  }
}

export function useGetCurrentUiPrice(info?: PumpToken) {
  const { cacheClmmInfo } = usePumpTokenListStore()
  const current_ui_price = useMemo(() => {
    if (info) {
      if (info.status >= BondingCurveStatus.MIGRATED) {
        return cacheClmmInfo[info.TokenDetail.clmm_pool]?.current_ui_price || info.current_ui_price
      }
      return info.current_ui_price
    }
    return undefined
  }, [info, cacheClmmInfo])

  return {
    current_ui_price
  }
}

