export function useGetAmountLimit(isBuy: boolean, swapResult?: CalculateSwapAmountResult) {
  const amountLimit = useMemo(() => {
    if (swapResult) {
      return PumpUtils.calculateAmountLimit(isBuy, swapResult)
    }

    return undefined
  }, [swapResult])

  return {
    amountLimit
  }
}
