import { StateCreator, create } from 'zustand'
import { persist } from 'zustand/middleware'

interface WebConfigState {
  /**
   * 用户许可
   */
  isTerm: boolean
  setIsTerm: (isTerm: boolean) => void
}

const store: StateCreator<WebConfigState> = (set, get) => ({
  isTerm: false,
  setIsTerm: (isTerm: boolean) => {
    set(() => ({
      isTerm
    }))
  }
})

const useWebConfigStore = create(persist(store, { name: 'useWebConfigStore', version: 3 }))
export default useWebConfigStore
