import { cancelBubble } from '@cetus/utils'
import { HStack, Skeleton, StackProps, Text, TextProps, Tooltip, TypographyProps, VStack } from '@chakra-ui/react'
import React from 'react'

const specialStrList = ['&', '/']

const formatLabel = (label: string | LeftLabel) => {
  const getLowerCaseLabel = (label: string) => {
    const strArray = label.split(' ')
    if (strArray.some(s => specialStrList.includes(s))) {
      return label
    } else {
      return strArray.map((s, i) => (i > 0 ? s.toLowerCase() : s)).join(' ')
    }
  }
  if (typeof label === 'object') {
    return label.toLowerCase ? getLowerCaseLabel(label.label) : label.label
  } else {
    return getLowerCaseLabel(label)
  }
}

type LeftLabel = {
  label: string
  toLowerCase?: boolean
}

type HTextLabelBoxProps = {
  leftLabel: string | LeftLabel
  leftLabelFontSize?: TypographyProps['fontSize']
  leftLabelColor?: string
  labelStyle?: TextProps
  leftTooltip?: string | JSX.Element
  textAlignItems?: string
  leftLabelBottom?: string
  leftLabelBottomColor?: string
  rightValue: string | JSX.Element
  valueStyle?: TextProps
  rightValueFontSize?: TypographyProps['fontSize']
  rightValueColor?: string
  rightValueTip?: string | JSX.Element
  rightValueBottom?: string | JSX.Element
  rightValueBottomColor?: string
  isLoading?: boolean
  skeletonStyle?: HTextLabelSkeleton
  wrapStyle?: StackProps
}

export default function HTextLabelBox(props: HTextLabelBoxProps) {
  const {
    leftLabel,
    labelStyle = {},
    leftLabelColor = 'text_paragraph',
    leftLabelFontSize = '12px',
    rightValueFontSize = '12px',
    textAlignItems = 'center',
    rightValue,
    valueStyle = {},
    rightValueTip,
    rightValueColor = 'text_caption',
    leftLabelBottom,
    leftLabelBottomColor,
    leftTooltip,
    rightValueBottom,
    rightValueBottomColor,
    isLoading,
    skeletonStyle,
    wrapStyle
  } = props

  return isLoading ? (
    <HTextLabelSkeleton {...skeletonStyle} {...props} />
  ) : (
    <HStack w="100%" justifyContent="space-between" alignItems={textAlignItems} {...(wrapStyle || {})}>
      <VStack alignItems="start" gap="1px">
        {leftTooltip ? (
          <Tooltip label={<Text fontSize="12px">{leftTooltip}</Text>} aria-label="Yield" ml="12px" mr="12px">
            <button onClick={e => cancelBubble(e)}>
              <Text cursor="help" textDecoration="underline dotted" fontSize="12px">
                {formatLabel(leftLabel)}
              </Text>
            </button>
          </Tooltip>
        ) : (
          <Text color={leftLabelColor} fontSize={leftLabelFontSize} {...labelStyle}>
            {formatLabel(leftLabel)}
          </Text>
        )}
        {leftLabelBottom && (
          <Text color={leftLabelBottomColor} fontSize="12px">
            {leftLabelBottom}
          </Text>
        )}
      </VStack>

      <VStack alignItems="end" gap="1px">
        {rightValueTip ? (
          <Tooltip label={<Text fontSize="12px">{rightValueTip}</Text>} aria-label="Yield" ml="12px" mr="12px">
            <button onClick={e => cancelBubble(e)}>
              <Text
                cursor="help"
                maxW="220px"
                color={rightValueColor}
                textDecoration="underline dotted"
                textAlign="start"
                fontSize="12px"
                {...valueStyle}
              >
                {rightValue}
              </Text>
            </button>
          </Tooltip>
        ) : (
          <Text textAlign="right" maxW="220px" color={rightValueColor} fontSize={rightValueFontSize} {...valueStyle}>
            {rightValue}
          </Text>
        )}
        {rightValueBottom && (
          <Text maxW="220px" color={rightValueBottomColor} fontSize="12px">
            {rightValueBottom}
          </Text>
        )}
      </VStack>
    </HStack>
  )
}

type HTextLabelSkeleton = {
  rightValueW?: string
  rightValueBottomW?: string
}

type HTextLabelSkeletonProps = HTextLabelSkeleton & HTextLabelBoxProps

function HTextLabelSkeleton(props: HTextLabelSkeletonProps) {
  const {
    rightValueW = '60px',
    rightValueBottomW = '80px',
    leftLabel,
    leftLabelColor = 'text_paragraph',
    leftLabelFontSize = '12px',
    rightValueFontSize = '12px',
    rightValue,
    leftLabelBottom,
    leftLabelBottomColor,
    leftTooltip,
    rightValueBottom,
    wrapStyle
  } = props
  return (
    <HStack w="100%" justifyContent="space-between" alignItems="center" {...wrapStyle}>
      <VStack alignItems="start" gap="1px">
        {leftTooltip ? (
          <Tooltip label={<Text>{leftTooltip}</Text>} aria-label="Yield">
            <button onClick={e => cancelBubble(e)}>
              <Text textDecoration="underline dotted" fontSize="12px">
                {formatLabel(leftLabel)}
              </Text>
            </button>
          </Tooltip>
        ) : (
          <Text color={leftLabelColor} fontSize={leftLabelFontSize}>
            {formatLabel(leftLabel)}
          </Text>
        )}
        {leftLabelBottom && (
          <Text color={leftLabelBottomColor} fontSize="12px">
            {leftLabelBottom}
          </Text>
        )}
      </VStack>

      <VStack alignItems="end" gap="1px">
        {(typeof rightValue === 'string' || React.isValidElement(rightValue)) && <Skeleton w={rightValueW} />}
        {rightValueBottom && typeof rightValueBottom === 'string' && <Skeleton w={rightValueBottomW} />}
      </VStack>
    </HStack>
  )
}
