import { SwapRouterData } from '@/types/swap'
import { CoinInfo } from '@cetus/types'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { StateCreator, create } from 'zustand'

interface SwapConfigState {
  fromCoin: CoinInfo | undefined
  toCoin: CoinInfo | undefined
  setFromCoin: (value: CoinInfo | undefined) => void
  setToCoin: (value: CoinInfo | undefined) => void

  byAmountIn: boolean
  setByAmountIn: (byAmountIn: boolean) => void

  fromAmount: string
  toAmount: string
  setFromAmount: (amount: string) => void
  setToAmount: (amount: string) => void

  findRouterLoading: boolean
  setFindRouterLoading: (loading: boolean) => void
  routerData?: SwapRouterData
  setRouterData: (data?: SwapRouterData) => void

  poolAddressMap: Record<string, string[]>
  setPoolAddressMap: (key: string, poolAddress: string[]) => void
}

const store: StateCreator<SwapConfigState> = (set, get) => ({
  poolAddressMap: {},
  byAmountIn: true,
  findRouterLoading: false,
  fromAmount: '',
  toAmount: '',
  fromCoin: envConfigs.clmm_swap.from_coin,
  toCoin: envConfigs.clmm_swap.to_coin,
  routerData: undefined,
  setFromCoin: (value: CoinInfo | undefined) => {
    set(() => ({
      fromCoin: value
    }))
  },
  setToCoin: (value: CoinInfo | undefined) => {
    set(() => ({
      toCoin: value
    }))
  },

  setFromAmount: (amount: string) => {
    set(() => ({
      fromAmount: amount
    }))
  },
  setToAmount: (amount: string) => {
    set(() => ({
      toAmount: amount
    }))
  },
  setRouterData: (data?: SwapRouterData) => {
    set(() => ({
      routerData: data
    }))
  },
  setFindRouterLoading: (loading: boolean) => {
    set(() => ({
      findRouterLoading: loading
    }))
  },
  setByAmountIn: (byAmountIn: boolean) => {
    set(() => ({
      byAmountIn
    }))
  },
  setPoolAddressMap: (key: string, poolAddress: string[]) => {
    const poolAddressMap = get().poolAddressMap
    poolAddressMap[key] = poolAddress
    set(() => ({
      poolAddressMap: { ...poolAddressMap }
    }))
  }
})

const useSwapStore = create(store)
export default useSwapStore
