import { useAccountStore } from '@cetus/stores'
import useClmmSDKStore from '@cetus/stores/src/useClmmSDKStore'
import { useSignAndExecuteTransaction, useSignTransaction } from '@mysten/dapp-kit'
import { SuiTransactionBlockResponse } from '@mysten/sui/client'
import { Transaction } from '@mysten/sui/transactions'
import { fromBase64 } from '@mysten/sui/utils'
import { SignedTransaction } from '@mysten/wallet-standard'
import { useMemo } from 'react'

export function useSigner() {
  const { clmmSdk } = useClmmSDKStore()
  const { currentAccount } = useAccountStore()
  const { mutateAsync: signTransaction } = useSignTransaction()

  const { mutate: signAndExecuteTransaction } = useSignAndExecuteTransaction({
    execute: async ({ bytes, signature }) =>
      await clmmSdk.fullClient.executeTransactionBlock({
        transactionBlock: bytes,
        signature,
        options: {
          showRawEffects: true,
          showEvents: true,
          showObjectChanges: true,
          showBalanceChanges: true
        }
      })
  })

  const chain = useMemo(() => {
    // TODO 取第0个链  是否正确？
    return currentAccount?.chains[0]
  }, [currentAccount])

  /**
   * 执行交易
   * @param sdk
   * @param rawBytes
   * @param signature
   * @returns
   */
  const executeTransactionBlock = async (rawBytes: string, signature: string | string[]) => {
    clmmSdk.fullClient.batchGetObjects
    const result = await clmmSdk.fullClient.executeTransactionBlock({
      transactionBlock: rawBytes,
      signature,
      options: {
        showEvents: true,
        showRawEffects: true,
        showEffects: true,
        showBalanceChanges: true,
        showObjectChanges: true,
        showInput: true
      }
    })

    if (result.errors) {
      throw new Error(JSON.stringify(result.errors) || 'Transaction failed')
    }

    return result
  }

  /**
   * 只签名，不发送交易
   * @param transactionBlock
   * @returns
   */

  const signTransactionBlock = async (transactionBlock: Uint8Array | Transaction | string): Promise<SignedTransaction | any> => {
    if (transactionBlock instanceof Uint8Array) {
      transactionBlock = Transaction.from(transactionBlock)
    }

    if (typeof transactionBlock === 'string') {
      transactionBlock = Transaction.from(fromBase64(transactionBlock))
    }

    return new Promise((resolve, reject) => {
      signTransaction(
        {
          transaction: transactionBlock as Transaction,
          chain
        },
        {
          onSuccess: result => {
            console.log('executed transaction', result)
            resolve(result)
          },
          onError: error => {
            console.error('transaction failed', error)
            reject(error)
          }
        }
      )
    })
  }

  /**
   *
   * @param tx
   * @returns
   */
  const signAndExecuteTransactionBlock = async (transactionBlock: Transaction, useDevInspect = false): Promise<SuiTransactionBlockResponse> => {
    let tx: Transaction

    if (typeof transactionBlock === 'string') {
      tx = Transaction.from(transactionBlock)
    } else {
      tx = transactionBlock
    }
    console.log('chain: ', {
      chain,
      transactionBlock
    })

    if (useDevInspect) {
      const res = await clmmSdk.fullClient.devInspectTransactionBlock({
        transactionBlock,
        sender: currentAccount!.address
      })

      console.log('devInspectTransactionBlock:', res)
    }
    // TODO 测试cetus pump时  在主网 迁移的tx 需要设置setGasBudget 钱包才能预计算通过，临时写死一个值？
    tx.setGasBudget(100000000)
    console.log('🚀 ~ file: useSigner.ts:71 ~ signTransactionBlock ~ transactionBlock:', transactionBlock)
    return new Promise((resolve, reject) => {
      signAndExecuteTransaction(
        {
          transaction: tx,
          chain
        },
        {
          onSuccess: result => {
            console.log(' signAndExecuteTransactionBlock  executed transaction', result)
            resolve(result)
          },
          onError: error => {
            console.error('signAndExecuteTransactionBlock transaction failed', error)
            reject(error)
          }
        }
      )
    })
  }

  return {
    signAndExecuteTransactionBlock,
    signTransactionBlock
  }
}
