import { useFileUpload } from '@/hooks'
import { replaceFilename } from '@/utils'
import Spinner from '@cetus/ui-kit/src/components/Spinner'
import { Box, Input, InputProps } from '@chakra-ui/react'
import { useDeepCompareEffect } from 'ahooks'
import dayjs from 'dayjs'
import { FieldInputProps, FormikProps } from 'formik'
import { forwardRef, useImperativeHandle, useRef, useState } from 'react'
import PreView from './PreView'

interface UploadProps extends Omit<InputProps, 'onChange' | 'form' | 'onSuccess' | 'onError'> {
  children?: React.ReactNode
  fileSize?: `${number}MB`
  loading?: boolean
  field: FieldInputProps<any[]>
  form: FormikProps<{}>
  onChange: (files: File[]) => void | Promise<void>
  onSuccess?: (file?: File) => void | Promise<void>
  onError?: (error: string) => void | Promise<void>
  onDelete?: (file?: File) => void | Promise<void>
}

const Upload = forwardRef(function Index(
  {
    w = '160px',
    h = '160px',
    loading,
    borderRadius = '12px',
    children,
    accept = 'image/png, image/jpeg',
    multiple = false,
    fileSize,
    field,
    form,
    onChange: onValueChange,
    onSuccess,
    onError,
    onDelete: handleDelete,
    ...rest
  }: UploadProps,
  ref
) {
  const uploadRef = useRef<HTMLInputElement>(null)
  const { uploadLoading, doUploadFile } = useFileUpload()

  const onUpload = async (file: File) => {
    if (file) {
      const res = await doUploadFile(file)
      return res
    }
  }

  const [files, setFiles] = useState<Array<File & { [key: string]: any }>>([])

  const onChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      if (e.target.files?.length) {
        const file = e.target.files[0]
        const extension = file.name.slice(file.name.lastIndexOf('.') + 1)
        const filename = `cetus_pump_${dayjs().unix()}.${extension}`
        const newFile = replaceFilename(file, filename)
        if (fileSize) {
          const size = fileSize.split('MB')[0]
          if (newFile.size > Number(size) * 1024 * 1024) {
            throw new Error('file size is over limit')
          }
        }
        const res = await onUpload(newFile)
        if (res?.error) {
          throw new Error(res?.error)
        }
        if (res?.url) {
          onSuccess?.()
        }
        const reader = new FileReader()
        reader.readAsDataURL(newFile)
        reader.onload = event => {
          if (event.type === 'load') {
            if (multiple) {
              const result = [
                ...files,
                {
                  name: filename,
                  type: newFile.type,
                  size: newFile.size,
                  lastModified: newFile.lastModified,
                  dataUrl: event.target?.result,
                  fileUrl: res?.url,
                  sig: res?.sig
                }
              ]
              setFiles(result as any)
            } else {
              const result = [
                {
                  name: filename,
                  type: newFile.type,
                  size: newFile.size,
                  lastModified: newFile.lastModified,
                  dataUrl: event.target?.result,
                  fileUrl: res?.url,
                  sig: res?.sig
                }
              ]
              setFiles(result as any)
            }
          }
        }
      }
    } catch (error) {
      console.log((error as unknown as Error).message, '(error as unknown as Error).message')
      onError?.((error as unknown as Error).message)
    } finally {
      form?.setFieldTouched(field.name, true)
    }
  }

  useDeepCompareEffect(() => {
    if (files) {
      onValueChange?.(files)
      if (field.name) {
        form?.setFieldValue?.(field.name, files)
      }
    }
  }, [files])

  const onEdit = async (current: { origin: any; cropped: any }) => {
    const res = await onUpload(current.cropped)
    const reader = new FileReader()
    reader.readAsDataURL(current.cropped)
    reader.onload = event => {
      if (event.type === 'load') {
        if (multiple) {
          const result = files.map(file => {
            if (file.name === current.cropped.name) {
              return {
                ...file,
                size: current.cropped.size,
                lastModified: current.cropped.lastModified,
                dataUrl: event.target?.result,
                fileUrl: res?.url,
                sig: res?.sig
              }
            }
            return file
          })
          setFiles(result as any)
        } else {
          const result = [
            {
              name: current.cropped.name,
              type: current.cropped.type,
              size: current.cropped.size,
              lastModified: current.cropped.lastModified,
              dataUrl: event.target?.result,
              fileUrl: res?.url,
              sig: res?.sig
            }
          ]
          setFiles(result as any)
        }
      }
    }
  }

  const onDelete = (current: File) => {
    handleDelete?.()
    setFiles(files.filter(file => file.name !== current.name))
    if (uploadRef.current) {
      uploadRef.current.value = ''
    }
  }

  const onClear = () => {
    setFiles([])
    if (uploadRef.current) {
      uploadRef.current.value = ''
    }
  }

  useImperativeHandle(ref, () => {
    return {
      handleClear: onClear
    }
  }, [uploadRef.current])

  return (
    <Box w={w} h={h} borderRadius={borderRadius} onClick={() => uploadRef.current?.click()} {...rest} cursor="pointer">
      {loading || uploadLoading ? (
        <Spinner />
      ) : files.length ? (
        files?.map((file, index) => {
          if (file.type.startsWith('image')) {
            return <PreView editable key={file.sig || index} src={file.fileUrl} file={file} onEdit={onEdit} onDelete={onDelete} />
          } else {
            return (
              <Box as="a" target="_blank" key={file.sig || index} download={file.fileUrl}>
                {file.name}
              </Box>
            )
          }
        })
      ) : (
        children
      )}
      <Input ref={uploadRef} id="file" name="file" type="file" display="none" accept={accept} multiple={multiple} onChange={onChange} />
    </Box>
  )
})

export default Upload
