import { CoinBalance } from '@mysten/sui/client'
import { StateCreator, create } from 'zustand'
import { persist } from 'zustand/middleware'

interface TokenState {
  isLoading: boolean
  ownerAddress: string | undefined
  setIsLoading: (isLoading: boolean) => void
  tokenBalanceObj: Record<string, CoinBalance>
  setTokenBalanceObj: (obj: Record<string, CoinBalance>, address: string) => void
  clearData: () => void
}

const store: StateCreator<TokenState> = (set, get) => {
  return {
    isLoading: false,
    ownerAddress: undefined,
    tokenBalanceObj: {},
    setTokenBalanceObj: (obj: Record<string, CoinBalance>, address: string) => {
      const { tokenBalanceObj, ownerAddress } = get()
      if (address !== ownerAddress) {
        set(() => ({
          tokenBalanceObj: {
            ...obj
          },
          ownerAddress: address
        }))
      } else {
        set(() => ({
          tokenBalanceObj: {
            ...tokenBalanceObj,
            ...obj
          },
          ownerAddress: address
        }))
      }
    },
    setIsLoading: (isLoading: boolean) => {
      set(() => ({
        isLoading
      }))
    },
    clearData: () => {
      set(() => ({
        tokenBalanceObj: {},
        ownerAddress: undefined
      }))
    }
  }
}

const useTokenBalanceStore = create(persist(store, { name: 'useTokenBalanceStore', version: 1 }))
export default useTokenBalanceStore
