import useTokenSelect from '@cetus/hooks/src/useTokenSelect'
import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { CoinInfo } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { symbolDataDisplayProcessing } from '@cetus/utils'
import { Box, Flex, Text } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import SingleTokenInfo from '../SingleTokenInfo'
import BalanceValue from './BalanceValue'

type TokenListProps = {
  onSelectToken: (tokenInfo: CoinInfo) => void
  keyword: string
  currentLabel: string
}
export default function TokenList(props: TokenListProps) {
  const { onSelectToken, keyword, currentLabel } = props
  const { delCollectToken, addCollectToken } = useTokenSelect()
  const [list, setList] = useState<Array<CoinInfo>>([])

  const { trustedList, filterTokenList, filterTokenLoading, collectObj } = useTokenSelectStore()
  useEffect(() => {
    if (filterTokenLoading) return
    if (keyword) {
      setList(filterTokenList)
    } else {
      if (currentLabel !== 'All') {
        setList(filterTokenList)
      } else {
        setList(trustedList)
      }
    }
  }, [keyword, filterTokenList, filterTokenLoading, currentLabel])

  return (
    <Box marginTop="12px" height="400px" overflow="scroll">
      {!filterTokenLoading
        ? list.map(tokenInfo => {
            return (
              <Flex
                key={tokenInfo.coin_type}
                height="68px"
                justifyContent="space-between"
                alignItems="center"
                cursor="pointer"
                userSelect="none"
                p="0 16px"
                _hover={{
                  bg: 'primary_opacity.10',
                  borderRadius: '8px'
                }}
                onClick={() => onSelectToken(tokenInfo)}
              >
                <SingleTokenInfo coinType={tokenInfo.coin_type} imgBoxStyle={{ w: '32px', h: '32px' }} symbolFontSize="16px" haveTooltip={true} />
                <Flex alignItems="center">
                  <Box textAlign="right">
                    <BalanceValue tokenInfo={tokenInfo} />
                    <Text>{symbolDataDisplayProcessing(tokenInfo?.balanceUSD)}</Text>
                  </Box>
                  {collectObj[tokenInfo.coin_type] ? (
                    <Icon
                      marginLeft="18px"
                      xlinkHref="#icon-icon_star_sel"
                      svgW="20px"
                      svgH="19px"
                      svgFill="primary"
                      svgHover="primary"
                      onClick={e => {
                        e.stopPropagation()
                        delCollectToken(tokenInfo)
                      }}
                    />
                  ) : (
                    <Icon
                      marginLeft="18px"
                      xlinkHref="#icon-icon_star"
                      svgW="20px"
                      svgH="19px"
                      variant="primary"
                      onClick={e => {
                        e.stopPropagation()
                        addCollectToken(tokenInfo)
                      }}
                    />
                  )}
                </Flex>
              </Flex>
            )
          })
        : ''}
    </Box>
  )
}
