import useGetPoolList from '@/hooks/pool/useGetPoolList'
import useVaultsStore from '@/store/vaults'
import { VaultApiInfo, VaultBaseInfo, VaultStatItem } from '@/types'
import { aprProcessing } from '@/utils/api-data-utils'
import { useFetch } from '@cetus/hooks'
import { symbolDataDisplayProcessing } from '@cetus/utils'

export default function useGetVaultList() {
  const { fetchByApi } = useFetch()
  const { getPoolList } = useGetPoolList()
  const { setVaultStatsObj, setVaultBaseList } = useVaultsStore()

  // 获取vaults基础信息列表
  const getVaultBaseList = async (): Promise<VaultBaseInfo[]> => {
    try {
      const res = await getPoolList({
        is_vaults: true,
        display_all_pools: false,
        has_mining: false,
        has_farming: true,
        no_incentives: false,
        order_by: '-vol',
        limit: 100,
        offset: 0
      })
      const list: VaultBaseInfo[] = res?.map((item: any) => {
        const coinAB = [item?.tokenA?.coin_type, item?.tokenB?.coin_type]
        const farmingRewards = item?.miningRewardList?.map((fItem: any) => item?.coinType)
        const miningRewards = item?.miningRewardList?.map((mItem: any) => item?.coinType)

        const vaultsRewards = Array.from(new Set([...coinAB, ...farmingRewards, ...miningRewards]))
        return {
          ...item,
          vaultsRewards // vaults奖励，因为farming和mining奖励拿不到详细信息，为保持统一只有coinType
        }
      })

      setVaultBaseList(list)
      return list
    } catch (error) {
      console.log('getVaultBaseList Error:', error)
    }

    setVaultBaseList([])
    return []
  }

  // 获取vaults统计信息(目前不支持单条查询, 详情可直接调用，然后在store的vaultsStatsObj中用key查询展示)
  const getVaultsStats = async () => {
    try {
      const res = await fetchByApi('/v2/sui/auto_pools', 'GET')
      const vaultsStatsObj: Record<string, VaultStatItem> = {}
      if (res?.pools) {
        res?.pools?.forEach((item: any) => {
          const clmmPoolAddress = item?.clmm_pool
          const vaultsId = item?.object_id
          const vaultsApy = item?.apr
          const vaultsApyDisplay = aprProcessing(vaultsApy, true)
          const vaultsTvl = item?.tvl
          const vaultsTvlDisplay = symbolDataDisplayProcessing(vaultsTvl, '$')
          vaultsStatsObj[clmmPoolAddress] = {
            vaultsApy,
            vaultsApyDisplay,
            clmmPoolAddress,
            vaultsId,
            vaultsTvl,
            vaultsTvlDisplay
          }
        })
        setVaultStatsObj(vaultsStatsObj)

        return vaultsStatsObj
      }
    } catch (error) {
      console.error('getVaultsStats Error:', error)
    }

    setVaultStatsObj({})
    return {}
  }

  // 获取vaults列表
  const getVaultList = async (orderBy: '-tvl' | '-apy' = '-tvl'): Promise<VaultApiInfo[]> => {
    try {
      const baseList = await getVaultBaseList()
      const statsObj = await getVaultsStats()

      const list = baseList?.map((item: any) => {
        const statsItem = statsObj?.[item.poolAddress]
        return {
          ...item,
          vaultsTvl: statsItem?.vaultsTvl || '--',
          vaultsTvlDisplay: statsItem?.vaultsTvlDisplay || '--',
          vaultsApy: statsItem?.vaultsApy || '--',
          vaultsApyDisplay: statsItem?.vaultsApyDisplay || '--',
          vaultsId: statsItem?.vaultsId || ''
        }
      })

      return list?.sort((a: any, b: any) => {
        if (orderBy === '-apy') {
          return b.vaultsApy - a.vaultsApy
        } else {
          return b.vaultsTvl - a.vaultsTvl
        }
      })
    } catch (error) {
      console.error('getVaultList Error:', error)
    }

    return []
  }

  return {
    getVaultBaseList,
    getVaultsStats,
    getVaultList
  }
}
