import envConfigs from '@cetus/types/src/config/envConfigs'
import { CetusPumpSDK } from '@cetusprotocol/cetus-sui-pump-sdk'
import { create, StateCreator } from 'zustand'

interface SDKState {
  pumpSdk: CetusPumpSDK
  setPumpSdk: (sdk: CetusPumpSDK) => void
}

const store: StateCreator<SDKState> = (set, get) => ({
  pumpSdk: new CetusPumpSDK(envConfigs.pump_sdk_options),
  setPumpSdk: (sdk: CetusPumpSDK) => {
    set(() => ({
      pumpSdk: sdk
    }))
  }
})

const usePumpSDKStore = create(store)
export default usePumpSDKStore
