import { Icon } from '@cetus/ui-kit'
import { Center, HStack, VStack } from '@chakra-ui/react'

type ToastProps = {
  onClose?: () => void
  children: any
}

export default function CustomToast(props: ToastProps) {
  const { children, onClose } = props

  return (
    <HStack
      w="440px"
      // minH="104px"
      // maxW="440px"
      bg="background"
      border="2px"
      borderColor="border"
      borderRadius="12px"
      p="16px"
      position="relative"
      gap="16px"
      sx={{
        '@media screen and (max-width: 810px)': {
          w: 'unset',
          minW: '330px',
          p: '16px'
        }
      }}
    >
      <VStack w="100%" alignItems="start">
        {children}
      </VStack>

      {/* 关闭按钮 */}
      <Center onClick={onClose} position="absolute" right="16px" top="16px">
        <Icon xlinkHref="#icon-icon_close" variant="gray" />
      </Center>
    </HStack>
  )
}
