import { CoinInfo } from '@cetus/types'
import { create, StateCreator } from 'zustand'
interface TokenSelectStore {
  collectList: Array<CoinInfo>
  setCollectList: (list: Array<CoinInfo>) => void
  collectObj: {
    [key: string]: CoinInfo
  }
  trustedList: Array<CoinInfo>
  setTrustedList: (list: Array<CoinInfo>) => void
  filterTokenLoading: boolean
  setFilterTokenLoading: (value: boolean) => void
  filterTokenList: Array<CoinInfo>
  setFilterTokenList: (list: Array<CoinInfo>) => void
}
const store: StateCreator<TokenSelectStore> = (set, get) => ({
  collectList: [],
  collectObj: {},
  setCollectList: (list: Array<CoinInfo>) => {
    set(() => ({
      collectList: list,
      collectObj: Object.fromEntries(list.map(item => [item.coin_type, item]))
    }))
  },
  trustedList: [],
  setTrustedList: (list: Array<CoinInfo>) => {
    set(() => ({
      trustedList: list
    }))
  },
  filterTokenLoading: false,
  setFilterTokenLoading: (value: boolean) => {
    set(() => ({
      filterTokenLoading: value
    }))
  },
  filterTokenList: [],
  setFilterTokenList: (list: Array<CoinInfo>) => {
    set(() => ({
      filterTokenList: list
    }))
  }
})

const useTokenSelectStore = create(store)
export default useTokenSelectStore
