import { CopyButton } from '@cetus/ui-kit'
import Icon from '@cetus/ui-kit/src/components/Icon'
import { HStack, StackProps, TextProps } from '@chakra-ui/react'
import AddressUnderLine from './AddressUnderline'

interface AddressCopyLinkProps extends TextProps {
  address: string
  onClickLink: () => void
  showCopy?: boolean
  showLink?: boolean
  addressWeight?: string
  addressColor?: string
  addressSize?: string
  hasUnderline?: boolean
  wrapStyle?: StackProps
}
export default function AddressCopyLink(props: AddressCopyLinkProps) {
  const {
    address,
    addressSize = '12px',
    showCopy = true,
    showLink = true,
    hasUnderline = true,
    addressWeight = '400',
    addressColor = 'text_paragraph',
    onClickLink,
    wrapStyle = { gap: '4px' },
    ...rest
  } = props
  return (
    <HStack align="center" {...wrapStyle}>
      <AddressUnderLine address={address} hasUnderline={hasUnderline} onClickLink={onClickLink} {...rest} />
      {showCopy && <CopyButton text={address} />}
      {showLink && <Icon xlinkHref="#icon-icon_link" onClick={onClickLink} />}
    </HStack>
  )
}
