import { uploadFilePath } from '@/type/api'
import { UploadResult } from '@/type/pump'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { useState } from 'react'

export function useFileUpload() {
  const [uploadLoading, setUploadLoading] = useState<boolean>(false)

  const doUploadFile = async (file: File): Promise<UploadResult | undefined> => {
    const formData = new FormData()
    formData.append('file', file)

    try {
      setUploadLoading(true)
      const api = `${envConfigs.pump_api.api_primary_domain}${uploadFilePath}`
      const response = await fetch(api, {
        method: 'POST',
        body: formData
      })

      if (!response.ok) {
        const { error } = await response.json()
        if (error) {
          throw new Error(error)
        } else {
          throw new Error('Upload failed')
        }
      }

      const result = await response.json()

      console.log('🚀 ~ file: useFileUpload.tsx:26 ~ doUploadFile ~ result:', result)
      return result
    } catch (error) {
      console.log('🚀 ~ file: useFileUpload.tsx:29 ~ doUploadFile ~ error:', (error as unknown as Error).message)
      throw new Error((error as unknown as Error).message)
    } finally {
      setUploadLoading(false)
    }
  }

  return {
    doUploadFile,
    uploadLoading
  }
}
