import { CoinInfo } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { HStack, Text, useDisclosure } from '@chakra-ui/react'
import TokenAvatar from './TokenAvatar'
import TokenSelectModal from './tokenSelectModal'

interface CoinSelectProps {
  value: CoinInfo
  onSelect: (value: CoinInfo) => void
}

function CoinSelect({ value, onSelect }: CoinSelectProps) {
  const { isOpen, onOpen, onClose } = useDisclosure()

  return (
    <>
      <HStack onClick={onOpen} cursor="pointer">
        <TokenAvatar src={value?.logo_url || ''} />
        <Text>{value?.symbol}</Text>
        <Icon xlinkHref="#icon-icon_arrow" fontSize="12px" />
      </HStack>
      <TokenSelectModal
        isOpen={isOpen}
        onSelectToken={(tokenInfo: CoinInfo) => {
          onSelect(tokenInfo)
        }}
        onClose={onClose}
      />
    </>
  )
}

export default CoinSelect
