import { useGetGlobalConfig } from '@/hook/pump/useGetGlobalConfig'
import { useGetMaxAmount } from '@/hook/pump/useGetMaxAmount'
import { useGetPublishFee } from '@/hook/pump/useGetPublishFee'
import { usePumpTrade } from '@/hook/pump/usePumpTrade'
import { CreateTokenModelOptions, PublishFee } from '@/type/pump'
import { TradeInputGroup } from '@cetus/design'
import { Tab } from '@cetus/design/src/components/common/SelectTab'
import { useInitSDK } from '@cetus/hooks'
import useGlobalToast from '@cetus/hooks/src/useGlobalToast'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { HTextLabelBox } from '@cetus/ui-kit'
import { addComma, d, fromDecimalsAmountFix } from '@cetus/utils'
import { CoinAssist, fromDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurveStatus, PumpUtils, TokenFee } from '@cetusprotocol/cetus-sui-pump-sdk'
import { Box, Button, HStack, Image, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import FeeSelect from '../common/FeeSelect'

type CreateTokenStepTwoProps = {
  options: CreateTokenModelOptions
  verifyToken: boolean
  onClose: () => void
}

export function CreateTokenStepTwo(props: CreateTokenStepTwoProps) {
  const { onClose, options, verifyToken } = props
  const { tokenTicker, onSkipClick, stepIndex, tokenName, token, onBuyClick, deploymentFee } = options

  const { pumpSdk } = useInitSDK()
  const { globalConfig } = useGetGlobalConfig()
  const { showCommonToast } = useGlobalToast()
  const [fee, setFee] = useState<TokenFee | undefined>(deploymentFee)

  const { publishFeeList } = useGetPublishFee()

  useEffect(() => {
    if (publishFeeList.length > 0) {
      const publishFee = publishFeeList[0]
      setFee({
        fee_amount: publishFee.amount,
        fee_coin_type: publishFee.coin_type,
        name: publishFee.name,
        symbol: publishFee.symbol,
        decimals: publishFee.decimals,
        iconUrl: publishFee.logo_url
      })
    }
  }, [])

  const { buyMaxAmountIn, buyMaxAmountOut, sellMaxAmountIn, sellMaxAmountOut } = useGetMaxAmount(
    PumpUtils.get_init_liquidity_from_sui(
      globalConfig?.bonding_curve_config.start_sqrt_price || '0',
      globalConfig?.bonding_curve_config.end_sqrt_price || '0',
      globalConfig?.bonding_curve_config.sui_amount || '0'
    ),
    globalConfig?.bonding_curve_config.start_sqrt_price,
    globalConfig?.bonding_curve_config.start_sqrt_price,
    globalConfig?.bonding_curve_config.end_sqrt_price,
    BondingCurveStatus.RAISING
  )

  const remain_sui = useMemo(() => {
    if (fee === undefined) {
      return '0.05'
    }
    const isSuiFeeCoin = CoinAssist.isSuiCoin(fee.fee_coin_type)
    const remainAmount = isSuiFeeCoin
      ? d(0.05)
          .add(fromDecimalsAmount(fee.fee_amount, fee.decimals || 9))
          .toString()
      : '0.05'

    return remainAmount
  }, [deploymentFee])

  const {
    payCoin,
    receiveCoin,
    payBalance,
    receiveBalance,
    payAmount,
    receiveAmount,
    handleAmountChange,
    calculateSwapResult,
    byAmountIn,
    btnText,
    btnDisabled,
    warnInfo
  } = usePumpTrade(
    {
      buyMaxAmountIn,
      buyMaxAmountOut,
      sellMaxAmountIn,
      sellMaxAmountOut
    },
    true,
    0,
    remain_sui,
    token?.bonding_curve_id,
    token?.coinInfo,
    envConfigs.sui_coin,
    true
  )

  const handleFeeChange = (value: Tab<PublishFee>) => {
    console.log('🚀 ~ file: CreateTokenStepTwo.tsx:85 ~ handleFeeChange ~ value:', value)
    const _fee = {
      fee_amount: value.amount,
      fee_coin_type: value.coin_type,
      name: value.name,
      symbol: value.symbol,
      decimals: value.decimals,
      iconUrl: value.logo_url
    }
    setFee(_fee)
  }

  const [actionIndex, setActionIndex] = useState<number>(0)
  const [verifyLoading, setVerifyLoading] = useState<boolean>(false)

  const handleVerifyToken = async (actionIndex: number) => {
    setActionIndex(actionIndex)
    setVerifyLoading(true)
    const isExist = await pumpSdk.pumpModule.isNameSymbolExist(tokenName, tokenTicker)
    if (isExist) {
      showCommonToast('Token name and symbol already exist.', 'rejected')
    }
    setVerifyLoading(false)
    return isExist
  }

  return (
    <VStack gap="20px" align="flex-start">
      <Text color="text_caption" fontSize="14px" mt="20px">
        {` Choose how many ${tokenName} (${tokenTicker}) you want to buy`}
      </Text>
      <TradeInputGroup
        icon="#icon-a-icon_trade"
        from={{
          title: 'You Pay',
          balance: payBalance?.balanceDisplay || '',
          value: payAmount,
          onChange: e => {
            handleAmountChange(e, true)
          },
          placeholder: '0.0',
          token: payCoin,
          handleHalfBalance: () => {
            if (payBalance) {
              handleAmountChange(d(payBalance.balanceFormat).div(2).toString(), true)
            }
          },
          handleMaxBalance: () => {
            if (payBalance) {
              const amount = d(payBalance.balanceFormat).sub(remain_sui)
              if (d(amount).gt(0)) {
                handleAmountChange(amount.toString(), true)
              }
            }
          }
        }}
        to={{
          title: 'You Receive',
          balance: receiveBalance?.balanceDisplay || '',
          value: receiveAmount,
          onChange: e => {
            handleAmountChange(e, false)
          },
          placeholder: '0.0',
          token: receiveCoin
        }}
      />
      <VStack gap="8px" w="100%">
        {/* 展示fee */}
        {deploymentFee && (
          <HTextLabelBox
            leftLabel="Deployment Fee"
            leftLabelColor="text_paragraph"
            leftLabelFontSize="14px"
            rightValue={
              <HStack justify="flex-end">
                <Image src={deploymentFee?.iconUrl} w="20px" h="20px" borderRadius="50%" />
                <Text
                  color="text_caption"
                  fontSize="14px"
                  fontWeight="500"
                  textAlign="right"
                >{`${addComma(fromDecimalsAmount(deploymentFee?.fee_amount || 0, deploymentFee?.decimals || 9))} ${deploymentFee?.symbol}`}</Text>
              </HStack>
            }
            rightValueColor="text_caption"
            rightValueFontSize="14px"
            wrapStyle={{
              p: {
                fontWeight: '500'
              }
            }}
          />
        )}

        {/* 选择fee */}
        {!deploymentFee && (
          <HStack w="100%" justifyContent="space-between">
            <Text color="text_paragraph">Deployment Fee</Text>
            <FeeSelect<TokenFee | undefined>
              value={fee}
              onChange={handleFeeChange}
              isActive={(current, tab) => (current as TokenFee)?.symbol === tab.symbol}
            />
          </HStack>
        )}
      </VStack>

      <HStack w="100%" gap="16px">
        <Button
          flex="1"
          variant="outline"
          h="42px"
          fontWeight="500"
          isLoading={actionIndex === 0 && verifyLoading}
          onClick={async () => {
            if (onSkipClick && fee) {
              const isExist = verifyToken ? await handleVerifyToken(0) : false
              if (!isExist) {
                onSkipClick({
                  fee_amount: fee.fee_amount,
                  fee_coin_type: fee.fee_coin_type
                })
              }
            }
          }}
        >
          Skip
        </Button>
        <Button
          flex="1"
          h="42px"
          fontWeight="500"
          isLoading={actionIndex === 1 && verifyLoading}
          onClick={async () => {
            if (onBuyClick && calculateSwapResult && fee) {
              const isExist = verifyToken ? await handleVerifyToken(1) : false
              if (!isExist) {
                onBuyClick(calculateSwapResult, {
                  fee_amount: fee.fee_amount,
                  fee_coin_type: fee.fee_coin_type
                })
              }
            }
          }}
          disabled={btnDisabled}
        >
          {btnText || 'Confirm'}
        </Button>
      </HStack>
      {warnInfo && (
        <Box
          p="10px 18px"
          borderRadius="12px"
          bg="primary_red_opacity.10"
          w="100%"
          mt="-8px"
          textAlign="start"
          cursor="pointer"
          onClick={() => {
            if (+warnInfo.amount) {
              handleAmountChange(fromDecimalsAmountFix(warnInfo.amount, 9), byAmountIn)
            }
          }}
        >
          <Text color="primary_red" fontSize="12px">
            {warnInfo.warnText}
          </Text>
        </Box>
      )}
    </VStack>
  )
}
