import { getCroppedImg } from '@/utils'
import { Icon } from '@cetus/ui-kit'
import {
  Box,
  Button,
  HStack,
  Modal,
  ModalBody,
  ModalCloseButton,
  ModalContent,
  ModalFooter,
  ModalHeader,
  ModalOverlay,
  Slider,
  SliderFilledTrack,
  SliderThumb,
  SliderTrack,
  Text
} from '@chakra-ui/react'
import { useState } from 'react'
import Cropper, { Area } from 'react-easy-crop'

interface CropImageProps {
  src: string
  dataUrl: string
  file: any
  open: boolean
  onClose: () => void
  onCancel?: () => void
  onOk: (file: any) => Promise<void>
}

export type CropParams = {
  croppedArea?: Area
  croppedAreaPixels?: Area
  zoom: number
}

function CropImage({ src, dataUrl, file, open, onClose, onCancel, onOk }: CropImageProps) {
  const [crop, setCrop] = useState({ x: 0, y: 0 })
  const [zoom, setZoom] = useState(1)
  const [cropping, setCropping] = useState(false)
  const [croppedAreaData, setCroppedAreaData] = useState<{ croppedArea: Area; croppedAreaPixels: Area } | null>(null)
  const onCropComplete = async (croppedArea: Area, croppedAreaPixels: Area) => {
    setCroppedAreaData({ croppedArea, croppedAreaPixels })
  }

  const onCropOk = async () => {
    setCropping(true)
    try {
      const croppedFile = await getCroppedImg(dataUrl, (croppedAreaData as any).croppedAreaPixels, file.name, file.type)
      await onOk(croppedFile)
    } catch (error) {
      console.error(error)
    } finally {
      setCropping(false)
    }
  }

  return (
    <Modal isOpen={open} onClose={onClose} isCentered>
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>
          <Box>
            <Text fontFamily="Inter, sans-serif" color="text_caption" fontSize="16px">
              Edit file
            </Text>
            <Text fontFamily="Inter, sans-serif">Crop and zoom on your image.</Text>
          </Box>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody>
          <Box position="relative" h="280px" w="100%" mb="12px">
            <Cropper
              image={src}
              crop={crop}
              zoom={zoom}
              aspect={1}
              showGrid={false}
              onCropChange={setCrop}
              onCropComplete={onCropComplete}
              onZoomChange={setZoom}
              style={{
                cropAreaStyle: {
                  border: '2px solid #76C8FF'
                }
              }}
            />
          </Box>
          <HStack p="0px 60px" gap="24px">
            <Icon
              xlinkHref="#icon-a-icon_zoomin"
              fontSize="20px"
              svgFill={zoom - 0.2 < 0.1 ? 'primary_disabled' : 'text_paragraph'}
              svgHover={zoom - 0.2 < 0.1 ? 'primary_disabled' : 'text_caption'}
              onClick={() => {
                if (zoom - 0.2 >= 0) {
                  setZoom(zoom - 0.2)
                }
              }}
            />
            <Slider aria-label="slider-ex-1" min={0.1} max={3} step={0.2} value={zoom} onChange={val => setZoom(val)}>
              <SliderTrack h="4px" bg="crop_slider_tracker">
                <SliderFilledTrack />
              </SliderTrack>
              <SliderThumb boxSize="4" />
            </Slider>
            <Icon
              xlinkHref="#icon-a-icon_zoomout"
              fontSize="20px"
              svgFill={zoom + 0.2 > 3 ? 'primary_disabled' : 'text_paragraph'}
              svgHover={zoom + 0.2 > 3 ? 'primary_disabled' : 'text_caption'}
              onClick={() => {
                if (zoom + 0.2 <= 3) {
                  setZoom(zoom + 0.2)
                }
              }}
            />
          </HStack>
        </ModalBody>

        <ModalFooter justifyContent="space-between" gap="16px">
          <Button variant="ghost" onClick={onCancel ? onCancel : onClose} flex="1" fontSize="14px">
            Cancel
          </Button>
          <Button flex="1" fontSize="14px" onClick={onCropOk} isLoading={cropping}>
            Save
          </Button>
        </ModalFooter>
      </ModalContent>
    </Modal>
  )
}

export default CropImage
