import { cancelBubble } from '@cetus/utils'
import { Center, HTMLChakraProps } from '@chakra-ui/react'
import copy from 'copy-to-clipboard'
import { useEffect, useState } from 'react'
import Icon from './Icon'

interface CopyButtonProps extends HTMLChakraProps<'div'> {
  text: string
  showRadiusBg?: boolean
}

export default function CopyButton(props: CopyButtonProps) {
  const { text, showRadiusBg = false } = props
  const [isClick, setIsClick] = useState(false)

  const handleClick = (e: any) => {
    if (isClick) return
    cancelBubble(e)

    copy(text, {
      debug: false,
      message: 'message'
    })
    setIsClick(!isClick)
  }

  useEffect(() => {
    if (isClick) {
      setTimeout(() => {
        setIsClick(false)
      }, 2000)
    }
  }, [isClick])

  if (showRadiusBg) {
    return (
      <Center w="32px" h="32px" bg="reward_modal_line" borderRadius="32px" cursor="pointer" onClick={handleClick}>
        <Icon xlinkHref={isClick ? '#icon-icon_tick' : '#icon-icon_copy'} />
      </Center>
    )
  }

  return (
    <>
      <Icon cursor="pointer" xlinkHref={isClick ? '#icon-icon_check' : '#icon-icon_copy'} onClick={handleClick} />
    </>
  )
}
