import { CoinPrice } from '@cetus/types/src/common-types'
import { StateCreator, create } from 'zustand'
import { persist } from 'zustand/middleware'

interface TokenState {
  coinPriceObj: Record<string, CoinPrice>
  setCoinObj: (obj: Record<string, CoinPrice>) => void
}

const store: StateCreator<TokenState> = (set, get) => {
  return {
    coinPriceObj: {},
    setCoinObj: (obj: Record<string, CoinPrice>) => {
      const tokensObj = get().coinPriceObj
      set({
        coinPriceObj: {
          ...tokensObj,
          ...obj
        }
      })
    }
  }
}

const useTokenPriceStore = create(persist(store, { name: 'useTokenPriceStore', version: 2 }))
export default useTokenPriceStore
