import { CustomToast, Toast } from '@cetus/design'
import { useToastStore } from '@cetus/stores'
import { ToastType, TransactionStatusType } from '@cetus/types/src/common-types'
import { useToast } from '@chakra-ui/react'
import React from 'react'

export default function useGlobalToast() {
  const { accumulateToastId } = useToastStore()
  const toast = useToast({
    position: 'top-right',
    duration: 3000
    // containerStyle: {
    // borderRadius: '16px',
    // border: '2px',
    // borderColor: 'border',
    // bg: 'background',
    // },
  })

  const getCurrentId = (transactionId?: string) => {
    if (transactionId) {
      return transactionId
    } else {
      return `toast${accumulateToastId()}`
    }
  }

  const closeToast = (transactionId: string) => {
    toast.close(transactionId)
  }

  const closeAllToast = () => {
    toast.closeAll()
  }

  const failedTsToast = (props: ToastType) => {
    const { transactionId } = props
    const currentId = getCurrentId(transactionId)
    toast({
      id: currentId,
      render: () => {
        return <Toast {...props} transactionId={currentId} status="rejected" onClose={() => toast.close(currentId)} />
      }
    })
    return currentId
  }

  const customToast = (children: React.ReactNode) => {
    const currentId = getCurrentId()
    toast({
      id: currentId,
      render: () => {
        return <CustomToast onClose={() => toast.close(currentId)}>{children}</CustomToast>
      }
    })
    return currentId
  }

  const successTsToast = (props: ToastType) => {
    const { transactionId } = props
    const currentId = getCurrentId(transactionId)
    toast({
      id: currentId,
      render: () => {
        return (<Toast {...props} transactionId={currentId} status="success" onClose={() => toast.close(currentId)} />) as React.ReactNode
      }
    })
    return currentId
  }

  const submittedTsToast = (props: ToastType) => {
    const { transactionId } = props
    const currentId = getCurrentId(transactionId)
    toast({
      id: currentId,
      render: () => {
        return (<Toast {...props} transactionId={currentId} status="submitted" onClose={() => toast.close(currentId)} />) as React.ReactNode
      }
    })
    return currentId
  }

  const showCommonToast = (text: string, status: TransactionStatusType = 'success') => {
    const currentId = getCurrentId()

    const info = {
      getShowInfo: () => {
        return {
          toastTitleText: text
        }
      }
    }

    toast({
      id: currentId,
      render: () => {
        return (<Toast {...info} transactionId={currentId} status={status} onClose={() => toast.close(currentId)} />) as React.ReactNode
      }
    })
    return currentId
  }

  return { closeToast, successTsToast, failedTsToast, submittedTsToast, closeAllToast, customToast, showCommonToast }
}
