import { SingleCoinImage } from '@cetus/ui-kit'
import { Box } from '@chakra-ui/react'

interface TokenAvatarProps {
  size?: string
  src: string
}

function TokenAvatar({ size = '38px', src }: TokenAvatarProps) {
  return (
    <Box w={size} h={size} p="5px" borderRadius="50%">
      <SingleCoinImage imageUrl={src} w="100%" h="100%" borderRadius="50%" />
    </Box>
  )
}

export default TokenAvatar
