import useTokenSelect from '@cetus/hooks/src/useTokenSelect'
import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { CoinInfo } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { Flex } from '@chakra-ui/react'
import { useState } from 'react'
import SingleTokenInfo from '../SingleTokenInfo'

type CollectListBoxProps = {
  onSelectToken: (tokenInfo: CoinInfo) => void
}
export default function CollectListBox(props: CollectListBoxProps) {
  const { onSelectToken } = props

  const { delCollectToken } = useTokenSelect()
  const { collectList } = useTokenSelectStore()
  const [hoverIconIndex, setHoverIconIndex] = useState(-1)

  return (
    <Flex flexWrap="wrap" marginTop="12px">
      {collectList.map((tokenItem, index) => {
        return (
          <Flex
            key={tokenItem.coin_type}
            w="auto"
            h="48px"
            p="10px 16px"
            align="center"
            marginRight="8px"
            borderRadius="8px"
            background="bg_secondary"
            borderStyle="solid"
            border="1px"
            borderColor="border"
            marginBottom="12px"
            cursor="pointer"
            position="relative"
            userSelect="none"
            _hover={{
              background: 'menu_item_hover_bg'
            }}
            onClick={() => onSelectToken(tokenItem)}
            onMouseEnter={() => setHoverIconIndex(index)}
            onMouseLeave={() => setHoverIconIndex(-1)}
          >
            <SingleTokenInfo coinType={tokenItem.coin_type} imgBoxStyle={{ w: '28px', h: '28px' }} />
            {hoverIconIndex == index ? (
              <Icon
                xlinkHref="#icon-icon_close"
                variant="round"
                position="absolute"
                top="-8px"
                right="-8px"
                onClick={e => {
                  e.stopPropagation()
                  delCollectToken(tokenItem)
                }}
              />
            ) : null}
          </Flex>
        )
      })}
    </Flex>
  )
}
