import { CreateTokenModelOptions } from '@/type/pump'
import { Spinner } from '@cetus/ui-kit'
import { Button, HStack, Image, Text, VStack } from '@chakra-ui/react'
import { useMemo } from 'react'

type CreateTokenStepOneProps = {
  options: CreateTokenModelOptions
  onClose: () => void
}

export function CreateTokenStepOne(props: CreateTokenStepOneProps) {
  const { onClose, options } = props
  const { tokenTicker, showIndex, status } = options

  const descriptionText = useMemo(() => {
    if (status === 'confirmation' || status === 'submitted') {
      return `Create token (${showIndex}/2)`
    }
    if (status === 'rejected') {
      return `Create token  failed (${showIndex}/2)`
    }
  }, [status])
  return (
    <VStack>
      <VStack gap="16px">
        <Image src={status === 'rejected' ? '/images/img_transactionrejected@2x.png' : '/images/img_launch@2x.gif'} h="200px" alt="icon" />
        <HStack>
          {status !== 'rejected' && <Spinner />}
          <Text whiteSpace="nowrap" color="text_caption">
            {descriptionText}
          </Text>
        </HStack>
      </VStack>

      {status === 'rejected' && (
        <Button
          w="60%"
          mt="20px"
          onClick={() => {
            onClose()
          }}
        >
          Close
        </Button>
      )}
    </VStack>
  )
}
