import { suiPriorityConfigs } from '@/constant/sui-priority'
import { d, fixRounding } from '@cetus/utils'
import { TickUtil } from '@cetusprotocol/cetus-sui-clmm-sdk'

export function getPoolDirection(coinTypeA: string, coinTypeB: string): boolean {
  const indexA = suiPriorityConfigs.indexOf(coinTypeA)
  const indexB = suiPriorityConfigs.indexOf(coinTypeB)

  if (indexA === -1 && indexB === -1) {
    return true
  }

  if (indexA !== -1 && indexB === -1) {
    return false
  }

  if (indexA === -1 && indexB !== -1) {
    return true
  }

  return indexA > indexB
}

export const checkFullRange = (lowerTick: number, upperTick: number, tickSpacing: number) => {
  const maxTick = TickUtil.getMaxIndex(tickSpacing)
  const minTick = TickUtil.getMinIndex(tickSpacing)
  if (maxTick === upperTick && minTick === lowerTick) {
    return true
  }

  return false
}

// 计算coinA,coinB占比
export const calcCoinProportion = (amountA: string | number, amountB: string | number, currentPrice: string, isFullRange: boolean) => {
  if (isFullRange) {
    return {
      percentA: '50',
      percentB: '50'
    }
  }

  const totalAmount = d(amountB).plus(d(amountA).mul(currentPrice))
  const percentA = fixRounding(d(amountA).mul(currentPrice).div(totalAmount).mul(100).toString(), 2)
  const percentB = fixRounding(d(amountB).div(totalAmount).mul(100).toString(), 2)

  return {
    percentA,
    percentB
  }
}
