import { useAccountStore } from '@cetus/stores'
import useClmmSDKStore from '@cetus/stores/src/useClmmSDKStore'
import { ToastType } from '@cetus/types/src/common-types'
import { handleErrorMessages, parseOwnerBalanceChanges, sleepTime } from '@cetus/utils/src/common'
import { Transaction } from '@mysten/sui/transactions'
import useExplorer from './useExplorer'
import useGlobalToast from './useGlobalToast'
import { useSigner } from './useSigner'
import useTransactionModal from './useTransactionModal'

export default function useTransaction() {
  const { signAndExecuteTransactionBlock } = useSigner()
  const { currentAccount } = useAccountStore()
  const { clmmSdk } = useClmmSDKStore()
  const { transactionConfirmation, transactionSubmitted, transactionSuccess, transactionRejected } = useTransactionModal()
  const { submittedTsToast, failedTsToast, successTsToast, closeToast } = useGlobalToast()
  const { getExplorerUrl } = useExplorer()

  const MAX_RETRIES = 5
  const RETRY_DELAY = 2000

  async function getTransactionStatus(digest: string, attempt = 1): Promise<any> {
    console.log('🚀 ~ file: useTransaction.tsx:24 ~ getTransactionStatus ~ Checking transaction status, attempt:', attempt)

    try {
      const response = await clmmSdk.Pool.getSuiTransactionResponse(digest)

      console.log('🚀 ~ file: useTransaction.tsx:28 ~ getTransactionStatus ~ response:', response)

      if (response) {
        return response
      }
      throw new Error('Empty response')
    } catch (error) {
      console.error(`Attempt ${attempt} failed:`, error)

      if (attempt >= MAX_RETRIES) {
        throw new Error('Failed to fetch transaction status after maximum retries.')
      }

      // 延迟后继续下一次轮询
      await sleepTime(RETRY_DELAY)
      return getTransactionStatus(digest, attempt + 1)
    }
  }

  const signAndExecuteTransaction = async (tx: Transaction, toastType: ToastType) => {
    let txConfirmToastId: string | undefined
    // 确认中
    transactionConfirmation(toastType)

    try {
      const response = await signAndExecuteTransactionBlock(tx, true)
      console.log('🚀 ~ file: useTransaction.tsx:24 ~ signAndExecuteTransaction ~ response:', response)
      // 已提交链上
      transactionSubmitted(toastType)
      txConfirmToastId = submittedTsToast(toastType)
      toastType.link = getExplorerUrl(response.digest, 'tx')

      // 延迟1秒，从链上查询真实状态
      await sleepTime(RETRY_DELAY)
      // 关闭进度弹窗
      closeToast(txConfirmToastId)

      const res = await getTransactionStatus(response.digest, 0)

      console.log('🚀 ~ file: useTransaction.tsx:42 ~ signAndExecuteTransaction ~ res:', res)
      // "error": "InsufficientCoinBalance in command 0"
      if (!res || res.effects?.status.status === 'failure') {
        handleError(toastType, res.effects?.status.error)
      } else {
        // 成功
        const balanceChanges = parseOwnerBalanceChanges(res, currentAccount?.address, false)

        console.log('🚀 ~ file: useTransaction.tsx:48 ~ signAndExecuteTransaction ~ balanceChanges:', balanceChanges)
        const info = toastType.getShowInfo!('success', balanceChanges)
        toastType.getShowInfo = (_: any) => {
          return info
        }
        transactionSuccess(toastType)
        successTsToast(toastType)
      }

      return res
    } catch (error) {
      if (txConfirmToastId) {
        closeToast(txConfirmToastId)
      }

      handleError(toastType, error)
    }

    return undefined
  }

  const handleError = (toastType: ToastType, error: any) => {
    console.log('🚀 ~ file: useTransaction.tsx:114 ~ handleError ~ error:', error)

    if (toastType.getShowInfo) {
      const info = toastType.getShowInfo('confirmation')

      const errorString = handleErrorMessages(error)

      toastType.getShowInfo = (_: any) => {
        info.toastDescriptionContent = errorString
        info.modalDescriptionText = errorString
        return info
      }
      transactionRejected(toastType)
      failedTsToast(toastType)
    }
  }

  return {
    signAndExecuteTransaction,
    getTransactionStatus
  }
}
