import { useAccountStore } from '@cetus/stores'
import useClmmSDKStore from '@cetus/stores/src/useClmmSDKStore'
import usePeripherySDKStore from '@cetus/stores/src/usePeripherySDKStore'
import usePumpSDKStore from '@cetus/stores/src/usePumpSDKStore'
import useRpcConfigStore from '@cetus/stores/src/useRpcConfigStore'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { AggregatorClient, Env } from '@cetusprotocol/aggregator-sdk'
import CetusPeripherySDK from '@cetusprotocol/cetus-periphery-sdk'
import CetusClmmSDK from '@cetusprotocol/cetus-sui-clmm-sdk'
import { CetusPumpSDK } from '@cetusprotocol/cetus-sui-pump-sdk'
import { SuiClient } from '@mysten/sui/client'
import { useEffect } from 'react'

/**
 * SDK 初始化 统一在这个类中处理
 */
export function useInitSDK() {
  const { pumpSdk, setPumpSdk } = usePumpSDKStore()
  const { clmmSdk, setClmmSdk, aggregatorSDK, setAggregatorSDK } = useClmmSDKStore()
  const { peripherySdk, setPeripherySdk } = usePeripherySDKStore()
  const { currentNode } = useRpcConfigStore()
  const { currentAccount } = useAccountStore()

  /**
   * 初始化 ClmmSdk  和  aggregatorSDK PeripherySdk
   */
  useEffect(() => {
    const { sdkOptions, senderAddress } = clmmSdk
    if (currentNode.link !== sdkOptions.fullRpcUrl || senderAddress !== currentAccount?.address) {
      sdkOptions.fullRpcUrl = currentNode.link
      const newSdk = new CetusClmmSDK(sdkOptions)
      newSdk.senderAddress = currentAccount?.address || ''
      setClmmSdk(newSdk)

      const newAggregatorClient = new AggregatorClient(
        envConfigs.clmm_sdk_options.aggregatorUrl,
        currentAccount?.address || '',
        new SuiClient({ url: currentNode.link }),
        envConfigs.env === 'testnet' ? Env.Testnet : Env.Mainnet
      )
      setAggregatorSDK(newAggregatorClient)

      const { sdkOptions: peripherySdkOptions } = peripherySdk
      const newPeripherySdk = new CetusPeripherySDK(peripherySdkOptions, newSdk)
      setPeripherySdk(newPeripherySdk)
    }
  }, [currentNode.link, currentAccount?.address])

  /**
   * 初始化 PumpSDK
   */
  useEffect(() => {
    const { sdkOptions, senderAddress } = pumpSdk
    if (currentNode.link !== sdkOptions.fullRpcUrl || senderAddress !== currentAccount?.address) {
      sdkOptions.fullRpcUrl = currentNode.link
      const newSdk = new CetusPumpSDK(sdkOptions)
      newSdk.senderAddress = currentAccount?.address || ''

      setPumpSdk(newSdk)
    }
  }, [currentNode.link, currentAccount?.address])

  return {
    clmmSdk,
    pumpSdk,
    aggregatorSDK,
    peripherySdk
  }
}
