import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { CoinInfo } from '@cetus/types'
import { d } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { useMemo } from 'react'

export function usePriceImpact(fromToken?: CoinInfo, toToken?: CoinInfo, fromValue?: string, toValue?: string) {
  const { getTokenPrice } = useTokenPrice()

  const fromTokenPrice = getTokenPrice(fromToken?.coin_type)
  const toTokenPrice = getTokenPrice(toToken?.coin_type)

  /**
   * 兑换价格
   */
  const swapPrice = useMemo(() => {
    if (fromValue && toValue && +fromValue && +toValue) {
      return d(toValue).div(fromValue).toString()
    }
    return '0'
  }, [fromValue, toValue])

  /**
   * 市场价格
   */
  const marketPrice = useMemo(() => {
    if (toTokenPrice && fromTokenPrice && +swapPrice) {
      return d(fromTokenPrice.price).div(toTokenPrice.price).toString()
    }
    return undefined
  }, [fromTokenPrice?.price, toTokenPrice?.price, swapPrice])

  /**
   * 价差
   */
  const priceImpact = useMemo(() => {
    if (marketPrice && +swapPrice) {
      return d(swapPrice).sub(marketPrice).div(swapPrice).toFixed(10)
    }

    return undefined
  }, [marketPrice])

  /**
   * 价格提供源
   */
  const sources = useMemo(() => {
    const list = []
    if (fromTokenPrice) {
      list.push(fromTokenPrice.market)
    }

    if (toTokenPrice && !list.includes(toTokenPrice.market)) {
      list.push(toTokenPrice.market)
    }

    return list
  }, [fromTokenPrice?.market, toTokenPrice?.market])

  /**
   * 是否展示提示
   */
  const showPriceImpactTips = useMemo(() => {
    if (priceImpact) {
      return d(priceImpact).abs().gt(5)
    }
    return false
  }, [priceImpact])

  /**
   * 是否展示警告
   */
  const showPriceImpactWarn = useMemo(() => {
    if (priceImpact) {
      return d(priceImpact).abs().gt(10)
    }
    return false
  }, [priceImpact])

  return {
    swapPrice,
    marketPrice,
    priceImpact,
    sources,
    showPriceImpactTips,
    showPriceImpactWarn
  }
}
