import { useAccountStore } from '@cetus/stores'
import { CoinInfo } from '@cetus/types'
import { Icon, NumericFormatInput, SingleCoinImage } from '@cetus/ui-kit'
import { addComma, convertScientificToDecimal } from '@cetus/utils'
import { Box, BoxProps, Button, HStack, InputGroup, InputRightAddon, Skeleton, Text } from '@chakra-ui/react'
import { useState } from 'react'
import CoinSelect from './CoinSelect'

export interface TradeInputProps {
  title?: string
  value: string
  amountValue?: string
  onChange: (value: string) => void
  onFocusChange?: (focus: boolean) => void
  placeholder: string
  balance: string | number
  selectable?: boolean
  onTokenChange?: (token: any) => void
  token?: CoinInfo
  handleHalfBalance?: () => void
  handleMaxBalance?: () => void
  loading?: boolean
  inputAllowed?: boolean
  wrapStyle?: BoxProps
}
function TradeInput({
  title,
  value,
  amountValue,
  onFocusChange,
  onChange,
  placeholder = '0.0',
  balance,
  selectable,
  onTokenChange,
  token,
  handleHalfBalance,
  handleMaxBalance,
  loading,
  inputAllowed = true,
  wrapStyle = {}
}: TradeInputProps) {
  const [focused, setFocused] = useState<boolean>(false)
  const { currentAccount } = useAccountStore()
  return (
    <Box
      bg="bg_secondary"
      borderRadius="20px"
      p="20px 16px"
      h="140px"
      borderTop="1px solid"
      borderBottom="1px solid"
      borderColor={focused ? 'border' : 'transparent'}
      mt="-1px"
      mb="-1px"
      sx={
        focused
          ? {
              position: 'relative',
              _before: {
                content: '""',
                position: 'absolute',
                top: '18px',
                left: '-1px',
                width: '1px',
                height: '102px',
                background: 'linear-gradient(360deg, rgba(26, 26, 26, 1), rgba(255, 255, 255, 1), rgba(26, 26, 26, 1))'
              },
              _after: {
                content: '""',
                position: 'absolute',
                top: '18px',
                right: '-1px',
                width: '1px',
                height: '102px',
                background: 'linear-gradient(360deg, rgba(26, 26, 26, 1), rgba(255, 255, 255, 1), rgba(26, 26, 26, 1))'
              }
            }
          : {}
      }
      {...wrapStyle}
    >
      <Text color="text_paragraph" fontSize="14px" fontWeight="500" h="20px" mb="10px" textAlign="left">
        {title}
      </Text>

      <InputGroup h="38px" mb="8px" fontFamily="Inter, sans-serif" gap="12px">
        <Skeleton isLoaded={!loading} height="38px" width="calc(100% - 8px)">
          <NumericFormatInput
            value={convertScientificToDecimal(value, 9)}
            onChange={onChange}
            decimals={token?.decimals}
            placeholder={placeholder}
            inputAllowed={inputAllowed}
            onFocus={() => {
              setFocused(true)
              if (onFocusChange) {
                onFocusChange(true)
              }
            }}
            onBlur={() => {
              setFocused(false)
              if (onFocusChange) {
                onFocusChange(false)
              }
            }}
            style={{
              width: 'calc(100% - 8px)',
              background: 'none',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              opacity: 1,
              outline: 'none',
              color: 'var(--chakra-colors-text_caption)',
              fontSize: '28px',
              height: '38px',
              lineHeight: '38px'
            }}
          />
        </Skeleton>

        <InputRightAddon>
          {selectable ? (
            <CoinSelect value={token} onSelect={onTokenChange!} />
          ) : (
            <HStack>
              <SingleCoinImage imageUrl={token?.logo_url} w="28px" h="28px" />
              <Text color="text_caption" fontSize="16px" fontWeight="600">
                {token?.symbol}
              </Text>
            </HStack>
          )}
        </InputRightAddon>
      </InputGroup>

      <HStack justify="space-between" w="100%">
        <Text>{amountValue && !!+amountValue ? `$${amountValue}` : null}</Text>

        {!!currentAccount && (
          <HStack justify="flex-end" gap="8px">
            <HStack gap="4px">
              <Icon xlinkHref="#icon-icon_wallet" svgHover="text_paragraph" cursor="default" />
              <Text>{!balance || balance === '0' ? '0.0' : addComma(balance)}</Text>
            </HStack>
            {handleHalfBalance && (
              <Button
                onClick={handleHalfBalance}
                fontSize="12px"
                fontWeight="500"
                lineHeight="20px"
                color="text_paragraph"
                w="42px"
                h="20px"
                borderRadius="4px"
                variant="outline"
              >
                Half
              </Button>
            )}
            {handleMaxBalance && (
              <Button
                onClick={handleMaxBalance}
                fontSize="12px"
                fontWeight="500"
                lineHeight="20px"
                color="text_paragraph"
                w="42px"
                h="20px"
                borderRadius="4px"
                variant="outline"
              >
                Max
              </Button>
            )}
          </HStack>
        )}
      </HStack>
    </Box>
  )
}

export default TradeInput
