import { CoinInfo } from '@cetus/types'
import { useEffect, useState } from 'react'
import { isHoneyPot } from 'suihoneypot'

/**
 * token 风险提示检查
 * @returns
 */
export default function useCheckTokenScamsAlert(coinInfo?: CoinInfo) {
  const [isScamsCoin, setIsScamsCoin] = useState<boolean | undefined>()

  const checkIsScamsCoin = async (coinInfo: CoinInfo) => {
    if (coinInfo.is_trusted) {
      return false
    }

    if (isScamsCoin !== undefined) {
      return isScamsCoin
    }

    try {
      const isScamsCoin = await isHoneyPot(coinInfo.coin_type)
      return isScamsCoin
    } catch (error) {
      console.log('🚀 ~ file: useCheckTokenScamsAlert.ts:19 ~ checkTokenScams ~ error:', error)
    }

    return false
  }

  useEffect(() => {
    setIsScamsCoin(undefined)
    if (coinInfo) {
      checkIsScamsCoin(coinInfo).then(res => {
        setIsScamsCoin(res)
      })
    }
  }, [coinInfo?.coin_type])

  return {
    isScamsCoin
  }
}
