import useSwapStore from '@/store/swap/swap'
import { AggregatorProvider, SwapRouterData, SwapRouterFormat } from '@/types/swap'
import { useGetToken } from '@cetus/hooks/src/useToken'
import { d, extractStructTagFromType } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { useMemo } from 'react'
import useGetPoolList from '../pool/useGetPoolList'

/**
 * 获取展示PriceAccept RouterData
 * @param originData
 * @returns
 */
export function useGetPriceAcceptRouterData(originData?: SwapRouterData) {
  const { routerData } = useSwapStore()

  const priceAcceptRouterData = useMemo(() => {
    if (routerData && originData) {
      if (originData.byAmountIn) {
        if (!d(originData.toAmountUi).eq(routerData.toAmountUi)) {
          return routerData
        }
      } else {
        if (!d(originData.fromAmountUi).eq(routerData.fromAmountUi)) {
          return routerData
        }
      }

      return undefined
    }
    return undefined
  }, [routerData, originData])

  return { priceAcceptRouterData }
}

/**
 * 计算交易的amountLimit
 * @param slippage
 * @param routerData
 * @returns
 */
export function useGetAmountLimit(slippage: string, routerData?: SwapRouterData) {
  const amountLimit = useMemo(() => {
    if (routerData) {
      const { byAmountIn, fromAmountUi, toAmountUi } = routerData
      if (byAmountIn) {
        return d(toAmountUi)
          .mul(d(1).sub(d(slippage).div(100)))
          .toString()
      } else {
        return d(fromAmountUi)
          .mul(d(1).add(d(slippage).div(100)))
          .toString()
      }
    }

    return undefined
  }, [slippage, routerData])

  return { amountLimit }
}

/**
 * 对RouterData 进行格式化处理
 * @returns
 */
export function useFormatSwapRouter(routerData?: SwapRouterData) {
  const { getTokenInfo, fetchTokenInfo } = useGetToken()
  const formatSwapRouter = useMemo(() => {
    if (routerData) {
      const providers: string[] = []
      const totalAmount = routerData.byAmountIn ? routerData.routerData.amountIn.toString() : routerData.routerData.amountOut.toString()
      const routers: any[] = []

      const notFoundList: string[] = []

      routerData.routerData.routes.forEach(route => {
        const routeF: any = {}
        const amount = routerData.byAmountIn ? route.amountIn.toString() : route.amountOut.toString()
        routeF.percentage = d(amount).div(totalAmount).toFixed(2)

        const pathsF: any[] = []

        route.path.forEach(path => {
          if (!providers.includes(path.provider)) {
            providers.push(path.provider)
          }

          const from_type = extractStructTagFromType(path.from).full_address
          const to_type = extractStructTagFromType(path.target).full_address

          const fromCoinInfo = getTokenInfo(from_type)
          const toCoinInfo = getTokenInfo(to_type)

          if (!fromCoinInfo) {
            if (notFoundList.includes(from_type)) {
              notFoundList.push(from_type)
            }
          }

          if (!toCoinInfo) {
            if (notFoundList.includes(to_type)) {
              notFoundList.push(to_type)
            }
          }

          pathsF.push({
            from_type,
            to_type,
            fee_rate: path.feeRate,
            provider: path.provider as AggregatorProvider
          })
        })

        routeF.paths = pathsF
        routers.push(routeF)
      })

      if (notFoundList.length > 0) {
        for (const info in notFoundList) {
          fetchTokenInfo(info)
        }
      }

      const info: SwapRouterFormat = {
        router_summery: `${routerData.routerData.routes.length} Streams`,
        providers: providers as AggregatorProvider[],
        routers
      }

      return info
    }
    return undefined
  }, [routerData])

  return { formatSwapRouter }
}

/**
 * 得到 swap 降级 池子地址列表
 * @returns
 */
export function useGetSwapPoolAddressList() {
  const { getPoolList, getLocalJsonPoolList } = useGetPoolList()
  const { poolAddressMap, setPoolAddressMap, fromCoin, toCoin } = useSwapStore()

  const getSwapPoolAddress = async () => {
    if (fromCoin && toCoin) {
      const sortedTypes = [fromCoin.coin_type, toCoin.coin_type].sort()
      const cacheKey = `${sortedTypes[0]}_${sortedTypes[1]}`
      const cacheValue = poolAddressMap[cacheKey]
      if (cacheValue) {
        return cacheValue
      }
      const params: any = {
        coin_type: `${fromCoin.coin_type},${toCoin.coin_type}`
      }

      let res = await getLocalJsonPoolList(params)

      if (res.list.length === 0) {
        res = await getPoolList(params)
      }

      if (res.list.length > 0) {
        const poolAddressList = res.list.map(pool => pool.poolAddress)
        if (poolAddressList.length > 0) {
          poolAddressMap[cacheKey] = poolAddressList
          setPoolAddressMap(cacheKey, poolAddressList)
          return poolAddressList
        }
      }
    }

    return []
  }

  return {
    getSwapPoolAddress
  }
}
