import { Box, Button, HStack, Image, Skeleton, Tag, Text, Tooltip, VStack } from '@chakra-ui/react'
import { ReactNode, isValidElement } from 'react'
import Icon from '../Icon'
import { PairTokenInfo, SingleTokenInfoH5 } from './Title'
import { Action, Cos, Divider, Double, Regular } from './ValueCell'
import { useTextColor } from './hooks'
import { FunctionNode, H5MapTableCells, H5MapTableProps, IBottomBtn, IBottomBtnItem, ILabel, ILogo, ITitle, TitleEnum } from './type'
import { renderNode } from './util'
const ItemsMap: Record<H5MapTableCells, (...args: any[]) => ReactNode> = {
  [H5MapTableCells.Regular]: Regular,
  [H5MapTableCells.Action]: Action,
  [H5MapTableCells.Divider]: Divider,
  [H5MapTableCells.Double]: Double,
  [H5MapTableCells.Cos]: Cos
}

const TitleMap: Record<TitleEnum, (...args: any[]) => ReactNode> = {
  [TitleEnum.SingleToken]: SingleTokenInfoH5,
  [TitleEnum.ST]: SingleTokenInfoH5,
  [TitleEnum.DoubleToken]: PairTokenInfo,
  [TitleEnum.DT]: PairTokenInfo
}

const Title = ({ data }: { data?: ITitle }) => {
  if (!data) return null
  const { type, ...rest } = data
  const Node = TitleMap[type]
  return <Node {...rest} />
}

const Bottom = ({ data }: { data?: FunctionNode | IBottomBtn | IBottomBtnItem }) => {
  if (typeof data === 'function') return data()
  if (isValidElement(data)) return data
  if (typeof data === 'object' && (data as IBottomBtn)?.data && Array.isArray((data as IBottomBtn)?.data)) {
    const { style, data: list } = data as IBottomBtn
    return (
      <HStack w="100%" justifyContent="space-between" {...style}>
        {(list as IBottomBtnItem[]).map(item => {
          const { text, render, ...rest } = item
          return (
            <Button key={item.key || item.text} {...rest}>
              {renderNode({ text, render })}
            </Button>
          )
        })}
      </HStack>
    )
  }
  if (typeof data === 'object') {
    const { text, render, ...rest } = data as IBottomBtnItem
    return <Button {...rest}>{renderNode({ text, render })}</Button>
  }
  return null
}

function H5MapTableItem({ data, children, loading, skeletonLength = 5, itemHeight = '40px', style, title, bottom, onClick }: H5MapTableProps) {
  const skeletonData = new Array(skeletonLength).fill(0)

  return (
    <VStack gap="0.5em" {...style} onClick={onClick}>
      {children}
      <Title data={title} />
      {loading ? (
        <>
          {skeletonData?.map((item, index) => (
            <HStack key={index} w="100%" justifyContent="space-between" alignItems="center" flexBasis={itemHeight}>
              <Skeleton h="16px" flex="1" />
              <Skeleton h="16px" flex="1" />
            </HStack>
          ))}
        </>
      ) : (
        <>
          {data?.map(item => {
            const { label, type, key, showLabel = true, hidden = false, ...rest } = item
            const Cell = ItemsMap[type]
            return (
              <Box key={key || label?.toString()} w="100%" mt={hidden ? '-8px' : '0'}>
                {!hidden && (
                  <HStack w="100%" justifyContent="space-between" alignItems="center" flexBasis={itemHeight}>
                    {showLabel && (
                      <HStack>
                        <Box>{renderNode(label)}</Box>
                        {typeof label === 'object' && (label as ILabel)?.tooltip && (
                          <Tooltip label={renderNode((label as ILabel)?.tooltip)}>
                            <Icon xlinkHref="#icon-icon_tips" cursor="help" />
                          </Tooltip>
                        )}
                      </HStack>
                    )}
                    <Cell {...rest} />
                  </HStack>
                )}
              </Box>
            )
          })}
        </>
      )}
      <Bottom data={bottom} />
    </VStack>
  )
}

const Logo = ({ name, logo, multiple, isLong }: ILogo) => {
  const { color, bg } = useTextColor({ isLong })
  return (
    <HStack flexBasis="32px" gap="8px">
      <Box flexBasis="32px">
        <Image borderRadius="50%" src={logo} />
      </Box>
      <VStack gap="2px" alignItems="flex-start">
        <Text flexBasis="14px" color="text_caption">
          {name}
        </Text>
        <Tag flexBasis="16px" color={color} bgColor={bg}>{`${multiple}x ${isLong ? 'Long' : 'Short'}`}</Tag>
      </VStack>
    </HStack>
  )
}
H5MapTableItem.Logo = Logo

export default H5MapTableItem
