export const fetchGet = async function (url: string, params?: any, timeout: number = 30000) {
  const list: any = []
  let allUrl: string = ''
  if (params) {
    for (const key in params) {
      const str = `${key}=${params[key]}`
      list.push(str)
    }
    const data = list.join('&')
    allUrl = `${url}?${data}`
  } else {
    allUrl = url
  }
  const controller = new AbortController()

  const timeoutId = setTimeout(() => {
    controller.abort()
  }, timeout)

  try {
    const res = await fetch(allUrl, { signal: controller.signal })
    clearTimeout(timeoutId)

    if (!res.ok) {
      throw new Error('Request failed')
    }

    const result: any = await res.json()
    return result?.data || result
  } catch (error: any) {
    clearTimeout(timeoutId)
    if (error.name === 'AbortError') {
      throw new Error('request time out')
    }
    throw error
  }
}

export const fetchPost = async function (url: string, params?: any, timeout: number = 30000) {
  // 创建一个 AbortController 实例
  const controller = new AbortController()

  // 设置超时
  const timeoutId = setTimeout(() => {
    controller.abort()
  }, timeout)

  try {
    const res = await fetch(url, {
      body: JSON.stringify(params),
      method: 'POST',
      signal: controller.signal
    })

    clearTimeout(timeoutId)

    if (!res.ok) {
      throw new Error('Request failed')
    }

    return res.json()
  } catch (error: any) {
    clearTimeout(timeoutId)

    if (error.name === 'AbortError') {
      throw new Error('request time out')
    }
    throw error
  }
}
const fetchAll = function (url: string, params?: any, method = 'GET', timeout: number = 30000) {
  if (method === 'GET' || method === 'get') {
    return fetchGet(url, params, timeout)
  }
  return fetchPost(url, params, timeout)
}
export default {
  fetchGet,
  fetchPost,
  fetchAll
}
