import { Box, HStack, Skeleton, SkeletonCircle, Text, VStack } from '@chakra-ui/react'
import CoinPairImage from '../CoinPairImage'
import SingleCoinImage from '../SingleCoinImage'
import TextWarp from '../TextWarp'
import { IDoubleTitle, SingleTokenData } from './type'

export const SingleTokenInfoSkeleton = () => {
  return (
    <HStack gap="4px" align="center">
      <SkeletonCircle size="9" />
      <VStack gap="4px" align="flex-start">
        <Skeleton />
        <Skeleton w="130px" />
      </VStack>
    </HStack>
  )
}

export const SingleTokenInfoH5 = ({ data }: { data: SingleTokenData }) => {
  const { loading, imageUrl, symbol, name } = data
  return (
    <>
      {loading ? (
        <SingleTokenInfoSkeleton />
      ) : (
        <HStack w="100%">
          <SingleCoinImage imageUrl={imageUrl} w="24px" h="24px" />
          <VStack
            align="flex-start"
            gap={{
              md: '0',
              lg: '0.5rem'
            }}
          >
            <Text color="text_caption">{symbol}</Text>
            <Text fontSize="12px">{name}</Text>
          </VStack>
        </HStack>
      )}
    </>
  )
}
export const DoubleTokenInfoSkeleton = () => {
  return (
    <HStack gap="4px" align="center">
      <SkeletonCircle size="9" />
      <Box ml="-20px">
        <SkeletonCircle size="9" />
      </Box>
      <VStack gap="4px" align="flex-start">
        <Skeleton />
        <Skeleton w="60px" />
      </VStack>
    </HStack>
  )
}

export const PairTokenInfo = ({ data, fee, loading }: Exclude<IDoubleTitle, 'type'>) => {
  return (
    <>
      {loading ? (
        <DoubleTokenInfoSkeleton />
      ) : (
        <HStack gap="0px" w="100%">
          <CoinPairImage w="40px" variant="border" coinAIconUrl={data[0]?.imageUrl} coinBIconUrl={data[1]?.imageUrl} />
          <VStack gap="0px" ml="8px" align="flex-start">
            <HStack>
              <TextWarp color="text_caption">{data[0]?.symbol}</TextWarp>
              <Text color="text_caption">-</Text>
              <TextWarp color="text_caption">{data[1]?.symbol}</TextWarp>
            </HStack>
          </VStack>
        </HStack>
      )}
    </>
  )
}
