import { Icon } from '@cetus/ui-kit'
import { HStack, Input, InputGroup, InputRightElement } from '@chakra-ui/react'

type SearchInputProps = {
  inputValue: string | number | readonly string[] | undefined
  changeInputValue: (value: string) => void
}
export function SearchInput(props: SearchInputProps) {
  return (
    <HStack bg="bg_primary">
      <InputGroup>
        <Input
          borderRadius="8px"
          h="48px"
          mr="2px"
          border="none"
          variant="outline"
          value={props.inputValue}
          onChange={e => {
            props.changeInputValue(e.target.value)
          }}
          textAlign="left"
          fontSize="sm"
          placeholder="Search by token or address"
          pr={{
            md: '36px',
            lg: '30px'
          }}
          pl={{
            md: '12px',
            lg: '16px'
          }}
        />
        <InputRightElement>
          {props.inputValue ? (
            <Icon
              xlinkHref="#icon-icon_close"
              position="absolute"
              top="14px"
              right="14px"
              onClick={e => {
                e.stopPropagation()
                props.changeInputValue('')
              }}
            />
          ) : null}
        </InputRightElement>
      </InputGroup>
    </HStack>
  )
}
