import numbro from 'numbro'
import { isNumeric } from './assertion'
import { Decimal } from './decimal'

export const d = (value?: Decimal.Value | undefined): Decimal.Instance => {
  if (Decimal.isDecimal(value)) {
    return value as Decimal
  }

  return new Decimal(typeof value === 'undefined' || value === 'undefined' || !value ? 0 : value)
}

// Add thousands separator to numbers
export const addComma = (value: string | number) => {
  try {
    const string = d(value).gt(1) ? numbro(value).format({ thousandSeparated: true }) : value // '1,000'
    return string
  } catch (error) {
    return value
  }
}

export const addCommaWithNoMantissa = (value: string | number) => {
  try {
    const string = d(value).gt(1) ? numbro(value).format({ thousandSeparated: true, mantissa: 0 }) : value // '1,000'
    return string
  } catch (error) {
    return value
  }
}

export const unformat = (value: string) => {
  if (value === '--') return '--'
  if (!value) return value
  return numbro.unformat(value)
}

// rounding
export const fixRounding = (value: string | number, decimal: number) => {
  const result = d(value).toDP(decimal, Decimal.ROUND_HALF_DOWN).toString()
  return result
}

export const fixNumber = (value: string | number, decimal: number, rounding: Decimal.Rounding) => {
  const result = d(value).toDP(decimal, rounding).toString()
  return result
}

// round down
export const fixDown = (value: string | number, decimal: number) => {
  try {
    const result = d(value).toDP(decimal, Decimal.ROUND_DOWN).toString()
    return result
  } catch (error) {
    return value
  }
}

// round up
export const fixUp = (value: string | number, decimal: number) => {
  const result = d(value).toDP(decimal, Decimal.ROUND_UP).toString()
  return result
}

// 去除小数位后面的0
export const removeDecimalZeros = (value: string) => {
  // 将字符串中所有非数字非小数点的字符都替换为空字符串，并且去除了连续的小数点，保留了小数点后的内容。
  try {
    return d(value.replace(/[^\d.]+|(\..*)\./g, '$1')).toString()
  } catch (error) {
    return ''
  }
}

export function getGtZeroIndex(value: string) {
  let i = 0
  if (value) {
    while (i < value.length) {
      if (d(value[i]).gt(0)) {
        return i + 1
      }
      i++
    }
  }
  return 0
}

export function getDecimalCount(val: string | number) {
  if (!isNumeric(val)) return 0
  const valAsNumber = Number(val)

  if (valAsNumber.toString() === valAsNumber.toExponential()) {
    return Math.abs(Number(valAsNumber.toString().split('e')[1] || 0))
  }
  if (valAsNumber > Number.MAX_SAFE_INTEGER) {
    console.warn('getDecimalCount: value is too large to get count.')
    return 0
  }

  if (Math.floor(valAsNumber) === valAsNumber) return 0
  return valAsNumber.toString().split('.')[1].length || 0
}

export function formatString2Number(value: string) {
  if (typeof value !== 'string') return value
  return value.split(',').join('')
}
