import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { cancelBubble } from '@cetus/utils'
import { Box, HTMLChakraProps, Text, Tooltip } from '@chakra-ui/react'
import { ReactNode, useRef, useState } from 'react'

interface TextWrapProps extends HTMLChakraProps<'div'> {
  children: ReactNode
  haveTooltip?: boolean
}

const TextWrap = ({ children, haveTooltip = true, ...rest }: TextWrapProps) => {
  const textRef = useRef(null)
  const [isShowTooltip, setIsShowToolTip] = useState(false)
  const checkOverflow = () => {
    const text: any = textRef.current
    if (text && text.scrollWidth > text.clientWidth) {
      setIsShowToolTip(true)
    } else {
      setIsShowToolTip(false)
    }
  }
  const { isApp } = useWindowWidth()
  return (
    <Box w="100%" onClick={e => cancelBubble(e)}>
      {isApp ? (
        <Text
          w="100%"
          fontSize="14px"
          color="text_caption"
          fontWeight="500"
          ref={textRef}
          whiteSpace="wrap"
          wordBreak="break-all"
          textAlign="right"
          {...rest}
        >
          {children}
        </Text>
      ) : isShowTooltip && haveTooltip ? (
        <Tooltip
          placement="top"
          label={
            <Text fontSize="14px" color="text_caption" fontWeight="500">
              {children}
            </Text>
          }
        >
          <button onClick={e => cancelBubble(e)}>
            <Text
              w="100%"
              fontSize="14px"
              color="text_caption"
              fontWeight="500"
              ref={textRef}
              overflow="hidden"
              whiteSpace="nowrap"
              textOverflow="ellipsis"
              onMouseEnter={checkOverflow}
              tabIndex={0} // 使元素可以获得焦点，以便键盘用户也能触发tooltip
              {...rest}
            >
              {children}
            </Text>
          </button>
        </Tooltip>
      ) : (
        <Text
          w="100%"
          fontSize="14px"
          color="text_caption"
          fontWeight="500"
          ref={textRef}
          overflow="hidden"
          whiteSpace="nowrap"
          textOverflow="ellipsis"
          onMouseEnter={checkOverflow}
          tabIndex={0} // 使元素可以获得焦点，以便键盘用户也能触发tooltip
          {...rest}
        >
          {children}
        </Text>
      )}
    </Box>
  )
}

export default TextWrap
