import { HistogramAllPath, HistogramPath } from '@/apis/path'
import { dayStrZeroPadding } from '@/utils/api-data-utils'
import { useFetch } from '@cetus/hooks'
import { Month } from '../common/useChartTime'

export type GetHistogramDataParams = {
  type: 'vol' | 'pure_tvl'
  date_type?: 'day' | 'wek' | 'mon'
  limit?: number
}

export default function useGetHistogramData() {
  const { fetchByApi } = useFetch()

  const getHistogramData = async (params: GetHistogramDataParams) => {
    const p: any = {
      typ: params?.type,
      date_type: params?.date_type || 'day'
    }

    if (params?.limit) {
      p['limit'] = params?.limit
    }

    const res = await fetchByApi(!p?.limit ? HistogramAllPath : HistogramPath, 'GET', p)
    console.log('🚀 ~ file: useGetHistogramData.ts:18 ~ getHistogramData ~ res:', res)

    const list = res?.list || []

    const result = list.map((item: any) => {
      const months = item.date.slice(5, 7)
      const mDateValue = Month[Number(months)]
      return {
        num: Number(item.num),
        date: item.date,
        month: params?.date_type == 'mon' ? mDateValue : dayStrZeroPadding(item.date)
      }
    })

    return result
  }

  return {
    getHistogramData
  }
}
