import { CreateTokenResult, PumpToken } from '@/type/pump'
import { CoinInfo } from '@cetus/types'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { CoinAssist, TickMath, extractStructTagFromType } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurve, BondingCurveStatus, MEMEDecimal, PumpUtils as cPumpUtils } from '@cetusprotocol/cetus-sui-pump-sdk'
import { SuiTransactionBlockResponse } from '@mysten/sui/client'
import { SUI_DECIMALS } from '@mysten/sui/utils'
import BN from 'bn.js'
export class PumpUtils {
  static parseCreateBondingCurveEvent(res: SuiTransactionBlockResponse): CreateTokenResult {
    const publishEvent = res.events?.find(event => event.type.includes('CreateBondingCurveEvent')) as any
    const parsedJson = publishEvent.parsedJson

    const token_type = extractStructTagFromType(parsedJson.coin_type.name).full_address
    const coin_metadata_id = parsedJson.coin_metadata_id
    const bonding_curve_id = parsedJson.bonding_curve_id
    const start_cap_id = parsedJson.start_cap_id

    const coinInfo: CoinInfo = {
      coin_type: token_type,
      decimals: Number(parsedJson.decimal),
      description: '',
      name: parsedJson.name,
      symbol: parsedJson.symbol,
      logo_url: parsedJson.url,
      id: coin_metadata_id
    }

    return {
      coinInfo,
      bonding_curve_id: bonding_curve_id as string,
      start_cap_id: start_cap_id as string
    }
  }

  static formatPumpToken(item: any, originToken?: PumpToken, resetData = true) {
    const detail = item.TokenDetail

    item.coin_type = extractStructTagFromType(item.coin_type).full_address
    detail.coin_type = extractStructTagFromType(detail.coin_type).full_address
    detail.symbol = detail.ticker
    detail.logo_url = detail.image
    item.status = cPumpUtils.getCurveInfoStatus(item.status)

    if (originToken) {
      item.current_ui_price = originToken.current_ui_price
      item.current_sqrt_price = originToken.current_sqrt_price
      item.liquidity = originToken.liquidity
      item.status = originToken.status
      item.sui_balance = originToken.sui_balance

      item.coin_a = originToken.coin_a
      item.coin_b = originToken.coin_b
    } else {
      //TODO 已迁移后，API接口返回的当前价格和流动性值不可信, 为了必现显示错误数据，故置空
      if (item.status > BondingCurveStatus.COMPLETED && resetData) {
        //TODO 随着测试进行 数据逐渐可信了，暂时注释掉
        // item.current_ui_price = undefined
        // item.current_sqrt_price = undefined
        // item.liquidity = undefined
        // item.coin_a = undefined
        // item.coin_b = undefined
      }
    }

    item.TokenDetail = detail

    return item
  }

  static parseBondingCurve(item?: BondingCurve, originInfo?: PumpToken, coinInfo?: CoinInfo) {
    if (item === undefined) {
      return undefined
    }
    const current_ui_price = TickMath.sqrtPriceX64ToPrice(new BN(item.current_sqrt_price), MEMEDecimal, SUI_DECIMALS).toString()
    const init_ui_price = TickMath.sqrtPriceX64ToPrice(new BN(item.start_sqrt_price), MEMEDecimal, SUI_DECIMALS).toString()

    if (originInfo) {
      const info: PumpToken = {
        ...originInfo,
        current_ui_price,
        current_sqrt_price: item.current_sqrt_price,
        status: item.status,
        balance: item.balance,
        sui_balance: item.sui_balance,
        total_volume: item.volume,
        liquidity: item.liquidity,
        TokenDetail: {
          ...originInfo.TokenDetail,
          clmm_pool: item.clmm_pool_id
        }
      }

      return info
    } else {
      if (coinInfo === undefined) {
        return undefined
      }

      const info: PumpToken = {
        token_info_id: item.id,
        total_volume: item.volume,
        volume_1h: '0',
        volume_24h: '0',
        volume_7d: '0',
        init_sqrt_price: item.start_sqrt_price,
        init_ui_price,
        current_sqrt_price: item.current_sqrt_price,
        current_ui_price,
        sqrt_price_change_24h: '0',
        price_change_1h: '0',
        price_change_24h: '0',
        price_change_total: '0',
        coin_type: item.coin_type,
        owner_balance: '0',
        balance: item.balance,
        sui_balance: item.sui_balance,
        pending_fee: item.pending_fee,
        total_fee: item.total_fee,
        end_sqrt_price: item.end_sqrt_price,
        liquidity: item.liquidity,
        status: item.status,
        TokenDetail: {
          name: coinInfo.name,
          symbol: coinInfo.symbol,
          ticker: coinInfo.symbol,
          coin_type: coinInfo.coin_type,
          description: coinInfo.description,
          discord: item.media_metadata.discord,
          image: coinInfo.logo_url || '',
          logo_url: coinInfo.logo_url || '',
          treasury_cap_id: '',
          start_cap_id: '',
          token_info_id: item.id,
          creator_address: item.creator,
          starter_address: item.creator,
          admin_address: '',
          package_id: '',
          owner_address: '',
          coin_metadata_id: coinInfo.id || '',
          twitter_link: item.media_metadata.twitter,
          telegram_link: item.media_metadata.telegram,
          website: item.media_metadata.website,
          decimals: coinInfo.decimals,
          clmm_pool: item.clmm_pool_id,
          lp_position: '',
          if_listed: false,
          market_cap: '',
          if_update_des: '',
          ready_block_limit: 0,
          list_on_dex_timestamp: 0,
          created_at: '',
          create_timestamp: '',
          iron_url_sig: ''
        },
        creator: ''
      }
      return info
    }
  }
}

export function isCetusCoin(coinType: string) {
  return extractStructTagFromType(envConfigs.cetus_coin.coin_type).full_address === extractStructTagFromType(coinType).full_address
}

export function getFeeCoin(coinType: string) {
  if (isCetusCoin(coinType)) {
    return envConfigs.cetus_coin
  }

  if (CoinAssist.isSuiCoin(coinType)) {
    return envConfigs.sui_coin
  }
  return undefined
}
