import { CacheClmmInfo, PumpToken } from '@/type/pump'
import { StateCreator, create } from 'zustand'

interface PumpTokenListState {
  // 列表刷新Loading
  pumpTokenListRefreshLoading: boolean
  setPumpTokenListRefreshLoading: (loading: boolean) => void

  // 列表加载更多Loading
  pumpTokenListLordMoreLoading: boolean
  setPumpTokenListLordMoreLoading: (loading: boolean) => void

  // Pump Token 列表
  pumpTokenList: PumpToken[]
  setPumpTokenList: (list: PumpToken[], isAppend: boolean) => void

  //是否有更多数据
  hasMoreData: boolean
  setHasMoreData: (hasMoreData: boolean) => void
  maxPage: number
  setMaxPage: (page: number) => void

  // 缓存Clmm 池子相关信息
  cacheClmmInfo: Record<string, CacheClmmInfo>
  setCacheClmmInfo: (info: CacheClmmInfo) => void
}

const store: StateCreator<PumpTokenListState> = (set, get) => ({
  maxPage: 0,
  cacheClmmInfo: {},
  hasMoreData: false,
  pumpTokenListLordMoreLoading: false,
  pumpTokenListRefreshLoading: false,
  pumpTokenList: [],
  setPumpTokenListRefreshLoading: (loading: boolean) => {
    set(() => ({
      pumpTokenListRefreshLoading: loading
    }))
  },
  setPumpTokenListLordMoreLoading: (loading: boolean) => {
    set(() => ({
      pumpTokenListLordMoreLoading: loading
    }))
  },
  setPumpTokenList: (list: PumpToken[], isAppend: boolean) => {
    set(state => ({
      pumpTokenList: isAppend ? [...state.pumpTokenList, ...list] : list
    }))
  },
  setHasMoreData: (hasMoreData: boolean) => {
    set({
      hasMoreData
    })
  },
  setCacheClmmInfo: (info: CacheClmmInfo) => {
    const cacheClmmInfo = get().cacheClmmInfo
    cacheClmmInfo[info.pool_id] = info
    set({
      cacheClmmInfo: { ...cacheClmmInfo }
    })
  },
  setMaxPage: (page: number) => {
    set({
      maxPage: page
    })
  }
})

const usePumpTokenListStore = create(store)
export default usePumpTokenListStore
