import useSwapStore from '@/store/swap/swap'
import useSwapConfigStore from '@/store/swap/swapConfig'
import { SwapRouterData } from '@/types/swap'
import { useAccountBalance, useDebounceFunction, useInitSDK } from '@cetus/hooks'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import useTransaction from '@cetus/hooks/src/useTransaction'
import { BalanceChanges, CoinInfo, CommonTypeInfo, TransactionStatusType } from '@cetus/types'
import { fromDecimalsAmountFix, getBalanceChanges } from '@cetus/utils'
import { BuildFastRouterSwapParams, FindRouterParams, RouterData, SwapInPoolsParams } from '@cetusprotocol/aggregator-sdk'
import { toDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { Transaction } from '@mysten/sui/transactions'
import BN from 'bn.js'
import { useEffect, useMemo, useRef, useState } from 'react'
import { v4 } from 'uuid'
import { useGetTokenBalance } from '../../../../hooks/src/useTokenBalance'
import useCheckTokenScamsAlert from '../common/useCheckTokenScamsAlert'
import { useGetAmountLimit, useGetSwapPoolAddressList } from './useSwapHelper'

export function useSwapHook() {
  const {
    fromCoin,
    toCoin,
    setFromCoin,
    setToCoin,
    setToAmount,
    fromAmount,
    toAmount,
    setFromAmount,
    routerData,
    setFindRouterLoading,
    setRouterData,
    setByAmountIn,
    byAmountIn
  } = useSwapStore()
  const { fetchTokenPrices, getTokenAmountValue } = useTokenPrice()
  const { slippage } = useSwapConfigStore()
  const { aggregatorSDK, clmmSdk } = useInitSDK()

  console.log('🚀 ~ file: useSwap.ts:39 ~ useSwapHook ~ clmmSdk:', clmmSdk.sdkOptions)

  const { signAndExecuteTransaction } = useTransaction()
  const { providersSwitchStates, supportOrderSplit } = useSwapConfigStore()
  const { fetchCoinBalance } = useAccountBalance()

  // 余额
  const { balanceInfo: fromBalanceInfo } = useGetTokenBalance(fromCoin)
  const { balanceInfo: toBalanceInfo } = useGetTokenBalance(toCoin)

  // 价值
  const fromAmountValue = getTokenAmountValue(fromCoin?.coin_type, fromAmount)
  const toAmountValue = getTokenAmountValue(toCoin?.coin_type, toAmount)

  const { getSwapPoolAddress } = useGetSwapPoolAddressList()

  const [uuid, setUuid] = useState<string>('')

  const uuidRef = useRef<string>('')
  const byAmountInRef = useRef<boolean>(true)
  const fromAmountRef = useRef<string>('')
  const toAmountRef = useRef<string>('')

  useEffect(() => {
    uuidRef.current = uuid
  }, [uuid])

  useEffect(() => {
    byAmountInRef.current = byAmountIn
  }, [byAmountIn])

  useEffect(() => {
    fromAmountRef.current = fromAmount
  }, [fromAmount])

  useEffect(() => {
    toAmountRef.current = toAmount
  }, [toAmount])

  /**
   * 预计算
   */
  const findRouters = async (amount: string, by_amount_in: boolean, uuid: string) => {
    if (fromCoin && toCoin && +amount) {
      const providersKeys = Object.entries(providersSwitchStates)
        .filter(([_, value]) => value === true)
        .map(([key, _]) => key)

      const formatAmount = toDecimalsAmount(amount, by_amount_in ? fromCoin.decimals : toCoin.decimals)
      const routerParams: FindRouterParams = {
        from: fromCoin.coin_type,
        target: toCoin.coin_type,
        amount: new BN(formatAmount),
        byAmountIn: by_amount_in,
        depth: 3,
        splitAlgorithm: undefined,
        splitFactor: undefined,
        splitCount: supportOrderSplit ? undefined : 1,
        providers: providersKeys
      }

      console.log('🚀 ~ file: useSwap.ts:26 ~ findRouters ~ routerParams:', routerParams)
      setFindRouterLoading(true)
      try {
        const res = await aggregatorSDK.findRouters(routerParams)

        if (!res || res.routes.length >= 0) {
          throw Error('not find router')
        }
        handleRouterData(false, res.insufficientLiquidity, by_amount_in, uuid, res)
      } catch (error) {
        console.log('🚀 ~ file: useSwap.ts:105 ~ findRouters ~ error:', error)

        const pools = await getSwapPoolAddress()

        const routerParams: SwapInPoolsParams = {
          from: fromCoin.coin_type,
          target: toCoin.coin_type,
          amount: new BN(formatAmount),
          byAmountIn: by_amount_in,
          pools
        }

        console.log('🚀 ~ file: useSwap.ts:115 ~ findRouters ~ routerParams:', routerParams)

        //走降级
        try {
          const res = await aggregatorSDK.swapInPools(routerParams)

          if (!res || !res.routeData) {
            //TODO
            throw Error('not find router')
          }
          handleRouterData(true, res.isExceed, by_amount_in, uuid, res.routeData)
        } catch (error) {
          console.log('🚀 ~ file: useSwap.ts:120 ~ swapInPools ~  error:', error)
          setRouterData(undefined)
        }
      } finally {
        setFindRouterLoading(false)
      }
    } else {
      resetInputAmount()
    }
  }

  const handleRouterData = (isDegrade: boolean, isExceed: boolean, by_amount_in: boolean, uuid: string, res: RouterData) => {
    console.log('🚀 ~ file: useSwap.ts:166 ~ handleRouterData ~ res:', {
      isDegrade,
      isExceed,
      routerData: res
    })
    if (toCoin && fromCoin) {
      const fromAmountUi = fromDecimalsAmountFix(res.amountIn.toString(), fromCoin.decimals).toString()
      const toAmountUi = fromDecimalsAmountFix(res.amountOut.toString(), toCoin.decimals).toString()

      const result: SwapRouterData = {
        routerData: res,
        fromAmountUi,
        toAmountUi,
        uuid,
        byAmountIn: by_amount_in,
        isExceed,
        isDegrade
      }

      console.log('🚀 ~ file: useSwap.ts:187 ~ handleRouterData ~ result:', result)

      if (uuidRef.current === uuid) {
        if (by_amount_in) {
          if (+fromAmountRef.current) {
            setToAmount(toAmountUi)
            setRouterData(result)
          } else {
            setToAmount('')
          }
        } else {
          if (+toAmountRef.current) {
            setFromAmount(fromAmountUi)
            setRouterData(result)
          } else {
            setFromAmount('')
          }
        }
      }
    }
  }

  const debouncedFindRouters = useDebounceFunction(findRouters, 500)

  // 输入不合法 清空router data
  useEffect(() => {
    if (+fromAmountRef.current && +toAmountRef.current) {
      return
    }
    setRouterData(undefined)
  }, [fromAmount, toAmount])

  /**
   * 输入数量监听
   * @param amount
   */
  const handleAmountChange = (amount: string, by_amount_in: boolean, resetInput: boolean = false) => {
    setByAmountIn(by_amount_in)
    if (by_amount_in) {
      setFromAmount(amount)
      if (resetInput) {
        setToAmount('')
      }
    } else {
      setToAmount(amount)
      if (resetInput) {
        setFromAmount('')
      }
    }

    if (+amount) {
      const uuid = v4()
      setUuid(uuid)
      debouncedFindRouters(amount, by_amount_in, uuid)
    } else {
      setFindRouterLoading(false)
      setRouterData(undefined)
      resetInputAmount()
    }
  }

  /**
   * 重新计算RouteData
   */
  const reCalculateRouteData = () => {
    const amount = byAmountInRef.current ? fromAmountRef.current : toAmountRef.current

    if (+amount) {
      const uuid = v4()
      setUuid(uuid)
      debouncedFindRouters(amount, byAmountInRef.current, uuid)
    }
  }

  /**
   * 切换token监听
   * @param coin
   * @param isFrom
   */
  const handleSelectToken = (coin: CoinInfo, isFrom: boolean) => {
    resetInputAmount()
    if (isFrom) {
      if (coin.coin_type === toCoin?.coin_type) {
        setToCoin(undefined)
      }
      setFromCoin(coin)
    } else {
      if (coin.coin_type === fromCoin?.coin_type) {
        setFromCoin(undefined)
      }
      setToCoin(coin)
    }
  }

  const { amountLimit } = useGetAmountLimit(slippage, routerData)

  const resetInputAmount = () => {
    setFromAmount('')
    setToAmount('')
    setFindRouterLoading(false)
    setRouterData(undefined)
  }

  // 监听token 切换 刷新价格
  useEffect(() => {
    const list = []
    if (fromCoin) {
      list.push(fromCoin.coin_type)
    }

    if (toCoin) {
      list.push(toCoin.coin_type)
    }

    if (list.length > 0) {
      fetchTokenPrices(list)
    }
  }, [fromCoin?.coin_type, toCoin?.coin_type])

  const getSwapSecondaryData = () => {
    return { ...routerData! }
  }

  /**
   * 执行swap
   * @param data
   */
  const doSwapAction = async (data: SwapRouterData) => {
    const { routerData, byAmountIn, fromAmountUi, toAmountUi } = data
    const txb = new Transaction()

    const params: BuildFastRouterSwapParams = {
      routers: routerData.routes,
      byAmountIn,
      slippage: Number(slippage),
      txb: txb
    }

    console.log('🚀 ~ file: useSwap.ts:261 ~ doSwapAction ~ params:', params)

    await aggregatorSDK!.fastRouterSwap(params)

    const res = await signAndExecuteTransaction(txb, {
      getShowInfo: (status: TransactionStatusType, balanceChanges?: Record<string, BalanceChanges>) => {
        const description = `Swapping ${fromAmountUi} ${fromCoin?.symbol} for ${toAmountUi} ${toCoin?.symbol}`

        const info: CommonTypeInfo = {
          modalDescriptionText: description,
          toastTitleText: description
        }

        if (status === 'success') {
          let payAmountF = fromAmountUi
          let receiveAmountF = toAmountUi

          if (balanceChanges) {
            payAmountF = getBalanceChanges(balanceChanges, fromCoin) || fromAmountUi
            receiveAmountF = getBalanceChanges(balanceChanges, toCoin) || toAmountUi
          }
          const description = `Swapping ${payAmountF} ${fromCoin?.symbol} for ${receiveAmountF} ${toCoin?.symbol}`

          info.toastDescriptionContent = description
        }

        return info
      }
    })

    console.log('🚀 ~ file: useSwap.ts:272 ~ doSwapAction ~ res:', res)

    if (res) {
      // 清空输入框
      resetInputAmount()
      //获取余额
      fetchCoinBalance()
    } else {
      // 如何失败 刷新一次路由计算
      reCalculateRouteData()
    }
  }

  // 风险token
  const { isScamsCoin: isFromScamsCoin } = useCheckTokenScamsAlert(fromCoin)
  const { isScamsCoin: isToScamsCoin } = useCheckTokenScamsAlert(toCoin)

  const scamsText = useMemo(() => {
    if (!isFromScamsCoin && !isToScamsCoin) {
      return undefined
    }

    if (isFromScamsCoin && isToScamsCoin) {
      return `${fromCoin?.symbol} and ${toCoin?.symbol}`
    }

    if (isFromScamsCoin) {
      return `${fromCoin?.symbol}`
    }

    if (isToScamsCoin) {
      return `${toCoin?.symbol}`
    }

    return undefined
  }, [isFromScamsCoin, isToScamsCoin])

  return {
    handleSelectToken,
    handleAmountChange,
    fromAmount,
    toAmount,
    fromAmountValue,
    toAmountValue,
    amountLimit,
    getSwapSecondaryData,
    reCalculateRouteData,
    fromBalanceInfo,
    toBalanceInfo,
    doSwapAction,
    scamsText
  }
}
