import { isValidElement, ReactNode } from 'react'
import { ColumnsType } from '../Table'
import { FunctionNode, H5MapTableCells, IBottomBtn, ILabel, ValueOption } from './type'

export const handleElement = ({ value }: { value: FunctionNode | ValueOption | ILabel | IBottomBtn }): [ReactNode, string | undefined] => {
  let element, color
  if (isValidElement(value) || typeof value === 'string' || typeof value === 'number') {
    element = value
  } else if (typeof value === 'function') {
    element = value()
  } else if (typeof value === 'object' && value !== null) {
    const { text, render } = value as ValueOption
    if ('color' in value) {
      color = value.color as string
    }
    if (text) {
      element = text
    } else if (render) {
      element = handleElement({ value: render })
    } else {
      throw new Error('You must select one of text or render to assign a valid value.')
    }
  } else {
    throw new Error('A valid value is required here.')
  }
  return [element, color]
}

export const renderNode = (node: FunctionNode | ValueOption | ILabel | IBottomBtn): ReactNode => {
  return handleElement({ value: node })[0]
}

export function transColumns2H5<T>(columns: ColumnsType<T>[], data: T, dataIndex?: number) {
  return columns.map(column => ({
    type: H5MapTableCells.Cos,
    label: column.title,
    showLabel: column?.showLabel,
    key: column.key,
    hidden: column.hidden ? (typeof column.hidden === 'function' ? column.hidden(data) : column.hidden) : false,
    value: typeof column.render === 'function' ? column.render(data, dataIndex) : column.render || data[column.key]
  }))
}
