import { useGetPublishFee } from '@/hook/pump/useGetPublishFee'
import { PublishFee } from '@/type/pump'
import { SelectTab } from '@cetus/design'
import { Tab } from '@cetus/design/src/components/common/SelectTab'
import { Skeleton } from '@chakra-ui/react'
import { useDeepCompareEffect } from 'ahooks'
import { useEffect, useState } from 'react'

interface FeeSelectProps<T> {
  list?: PublishFee[]
  isActive?: (currentTab: string | Tab<PublishFee> | T, tab: Tab<PublishFee>) => boolean
  value: string | Tab<PublishFee> | T
  onChange: (value: Tab<PublishFee>) => void
}

function FeeSelect<T>({ list, isActive, value, onChange }: FeeSelectProps<T>) {
  const [feeList, setFeeList] = useState<PublishFee[]>([])

  const { publishFeeList, fetchPublishFee } = useGetPublishFee()

  useEffect(() => {
    if (!list) {
      fetchPublishFee()
    } else {
      setFeeList(list)
    }
  }, [list])

  useDeepCompareEffect(() => {
    if (publishFeeList && publishFeeList.length > 0) {
      const suiIndex = publishFeeList.findIndex(item => item.symbol === 'SUI')
      if (suiIndex > -1) {
        const tempList = [...publishFeeList]
        const suiFee = tempList[suiIndex]
        tempList.splice(suiIndex, 1)
        setFeeList([suiFee, ...tempList])
      }
    }
  }, [publishFeeList])

  return (
    <Skeleton isLoaded={feeList.length > 0}>
      <SelectTab<PublishFee, T>
        type="outlineTab"
        tabList={(feeList || [])?.map(item => ({
          label: `${item?.amount_display} ${item?.symbol}`,
          imgInfo: { src: item?.logo_url || '', w: '20px', h: '20px', borderRadius: '50%' },
          ...item
        }))}
        wrapStyle={{
          h: '36px',
          p: '4px'
        }}
        itemStyle={{
          fontSize: '14px',
          gap: '4px',
          p: { base: '0 4px', lg: '0 20px' },
          borderRadius: '6px'
        }}
        isActive={isActive}
        currentTab={value}
        handleChangeTab={onChange}
      />
    </Skeleton>
  )
}

export default FeeSelect
