import { PublishFee } from '@/type/pump'
import { PumpGlobalConfig } from '@cetusprotocol/cetus-sui-pump-sdk'
import { StateCreator, create } from 'zustand'
import { persist } from 'zustand/middleware'

interface PumpConfigState {
  publish_fee_cache_time: number
  publishFeeList: PublishFee[]
  setPublishFeeList: (list: PublishFee[]) => void

  global_cache_time: number
  globalConfig?: PumpGlobalConfig
  setGlobalConfig: (config: PumpGlobalConfig) => void

  //外部链接提示
  externalLinkAlert: boolean
  setExternalLinkAlert: (alert: boolean) => void
}

const store: StateCreator<PumpConfigState> = (set, get) => ({
  externalLinkAlert: true,
  publish_fee_cache_time: 0,
  global_cache_time: 0,
  globalConfig: undefined,
  publishFeeList: [],
  setPublishFeeList: (list: PublishFee[]) => {
    set(() => ({
      publishFeeList: list,
      publish_fee_cache_time: new Date().getTime()
    }))
  },
  setGlobalConfig: (config: PumpGlobalConfig) => {
    set(() => ({
      globalConfig: config,
      global_cache_time: new Date().getTime()
    }))
  },
  setExternalLinkAlert: (alert: boolean) => {
    set(() => ({
      externalLinkAlert: alert
    }))
  }
})

const usePumpConfigStore = create(persist(store, { name: 'usePumpConfigStore', version: 2 }))
export default usePumpConfigStore
