import { CoinInfo } from '@cetus/types'
import { coinMetadataToCoinInfo } from '@cetus/utils'
import { CoinAssist, extractStructTagFromType } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { useCallback, useEffect, useMemo } from 'react'
import useTokenStore from '../../stores/src/token'
import useClmmSDKStore from '../../stores/src/useClmmSDKStore'

export function useGetToken(coinType?: string) {
  const { tokenMap, setToken, requestTokenList, addRequestTokenList } = useTokenStore()
  const { clmmSdk } = useClmmSDKStore()

  useEffect(() => {
    if (coinType) {
      if (!getTokenInfo(coinType)) {
        fetchTokenInfo(coinType)
      }
    }
  }, [coinType])

  const fetchTokenInfo = async (coinType: string): Promise<CoinInfo | undefined> => {
    try {
      // const info = getTokenInfo(coinType)
      // if (info) {
      //   return info
      // }
      if (requestTokenList.includes(coinType)) {
        return undefined
      }
      addRequestTokenList(coinType)
      const res = await clmmSdk.fullClient.getCoinMetadata({ coinType })
      if (res) {
        if (CoinAssist.isSuiCoin(coinType)) {
          res.iconUrl = '/images/icon-Sui@2x.png'
        }
        const token = coinMetadataToCoinInfo(res, coinType)
        setToken(token)
        console.log('🚀 ~ file: useToken.ts:38 ~ fetchTokenInfo ~ token:', token, requestTokenList)

        return token
      }
    } catch (error) {
      console.log('🚀 ~ file: useToken.ts:44 ~ fetchTokenInfo ~ error:', error)
    } finally {
    }

    return undefined
  }

  const getTokenInfo = useCallback(
    (coinType?: string) => {
      if (coinType) {
        return tokenMap.get(extractStructTagFromType(coinType).full_address) || tokenMap.get(coinType)
      }

      return undefined
    },
    [tokenMap]
  )

  const tokenInfo = useMemo(() => {
    return getTokenInfo(coinType)
  }, [coinType, tokenMap])

  return {
    tokenInfo,
    getTokenInfo,
    fetchTokenInfo
  }
}
